/* „Warum falsch?“ – zu jeder Grammatik- und Iʿrāb-Frage des Madina-Buchs die Gründe, warum die
   drei falschen Antworten nicht passen. Je Lektion: q = Grammatikfragen (l.quiz), i = Iʿrāb (l.irab),
   in derselben Reihenfolge; je Frage drei Gründe zu a[1], a[2], a[3]. Neue Fragen im Buch brauchen hier einen Eintrag an derselben Stelle. */
window.MADINA_WHY = {
"m01": {"q":[["مَنْ fragt nach Personen („Wer ist das?“), nicht nach Sachen.","أَ macht nur eine Ja/Nein-Frage: „Ist das …?“","أَيْنَ fragt nach dem Ort: „Wo ist das?“"],["مَا fragt nach Sachen: „Was?“","أَ ist die Fragepartikel für Ja/Nein-Fragen, kein „wer“.","لَا heißt „nein“."],["„Das Buch“ bräuchte den Artikel الْ: الْكِتَابُ – dann ohne Tanwīn.","Der Plural wäre كُتُبٌ; das Tanwīn sagt nichts über die Zahl.","Eine Frage entsteht durch أَ oder ein Fragewort, nicht durch das Tanwīn."],["هَذَا heißt „dies“; es ist das Subjekt, nicht „ist“.","Das Tanwīn heißt „ein“ (Unbestimmtheit), nicht „ist“.","بَيْتٌ heißt „ein Haus“ – das Prädikat, nicht „ist“."],["مَا fragt „Was?“ – „Was ist das Haus?“ ergibt keinen Sinn.","مَنْ fragt nach Personen („Wer?“).","أَ steht am Satzanfang, nicht vor dem Prädikat."],["Das ā nach dem h ist lang, auch wenn man es nicht schreibt.","hādhi gibt es nicht; die weibliche Form ist hādhihi (هَذِهِ).","hādhihi ist هَذِهِ „diese“ (weiblich), nicht هَذَا."]],"i":[]},
"m02": {"q":[["„dies (hier)“ ist هَذَا.","„wer?“ ist مَنْ.","„und“ ist وَ."],["وَ wird nie allein geschrieben, sondern an das nächste Wort gehängt.","وَ steht vorne, nicht hinten.","ذَلِكَ wird ohne Alif nach dem ذ geschrieben, obwohl man es lang spricht."],["Das ā ist lang (dhā-), auch wenn das Alif nicht geschrieben wird.","Im Zusammenhang wird ذَلِكَ mit -ka gesprochen.","dhāka (ذَاكَ) ist ein anderes, selteneres Wort."]],"i":[["Mubtadaʾ ist ذَلِكَ, das erste Wort; مَسْجِدٌ sagt etwas über ihn aus.","Kein Wort davor verlangt den Genitiv (keine Präposition, keine Iḍāfa); مَسْجِدٌ hat auch -un, nicht -in.","Im Nominalsatz gibt es kein Verb und daher kein Objekt; die Endung ist -un, nicht -an."]]},
"m03": {"q":[["Artikel und Tanwīn schließen sich aus: mit الْ steht nur ein einfaches Ḍamma.","Das Alif von الْ trägt ein Hamzatu l-waṣl, kein festes أَ, und Tanwīn geht mit الْ nicht.","Ohne الْ und ohne Tanwīn ist das Wort nicht bestimmt, sondern Muḍāf."],["ق ist ein Mondbuchstabe: al-qamaru, das l wird gesprochen.","ب ist ein Mondbuchstabe: al-baitu.","ك ist ein Mondbuchstabe: al-kitābu."],["Vor einem Sonnenbuchstaben wie ش wird das l angeglichen: ash-, nicht al-.","Mit Artikel gibt es kein Tanwīn, und das l wird angeglichen.","Hier fehlt der Artikel; الشَّمْسُ ist bestimmt."],["Nach وَ fällt das a von al weg (Hamzatu l-waṣl).","Mit Artikel gibt es kein Tanwīn (-un).","Der Artikel fehlt: الْبَيْتُ wird mit l gesprochen."],["كَبِيرٌ heißt „groß“.","قَصِيرٌ heißt „kurz“.","ثَقِيلٌ heißt „schwer“."],["جَمِيلٌ heißt „schön“.","خَفِيفٌ heißt „leicht“.","حَارٌّ heißt „heiß“."],["الْبَابُ hat den Artikel: „die Tür“, nicht „eine Tür“.","„Die offene Tür“ wäre الْبَابُ الْمَفْتُوحُ – das Adjektiv hätte dann auch الْ.","مَفْتُوحٌ heißt „offen“; „geschlossen“ wäre مُغْلَقٌ."]],"i":[["Khabar ist مَفْتُوحٌ; الْبَابُ ist das erste Wort, das Subjekt.","Es steht keine Präposition davor, und die Endung ist -u, nicht -i.","Kein Wort davor bildet eine Iḍāfa; الْبَابُ steht am Satzanfang."],["Mubtadaʾ ist الْبَابُ; مَفْتُوحٌ sagt etwas über ihn aus.","Ein Naʿt müsste bestimmt sein wie الْبَابُ (الْمَفْتُوحُ); مَفْتُوحٌ ist unbestimmt, also Prädikat.","Es gibt kein Verb, also kein Objekt; die Endung ist -un."],["Das Khabar steht im Nominativ (-un), nicht im Akkusativ.","Mubtadaʾ ist الْمَاءُ, das erste Wort.","Es steht keine Präposition davor; die Endung ist -un."]]},
"m04": {"q":[["Nach فِي steht der Genitiv (-i), nicht der Nominativ.","Nach فِي steht der Genitiv (-i), nicht der Akkusativ.","Für „im Haus“ braucht es den Artikel und den Genitiv: الْبَيْتِ."],["Nach عَلَى steht der Genitiv (-in), nicht der Nominativ.","Mit الْ gibt es kein Tanwīn, und nach عَلَى steht der Genitiv; außerdem „einem“ = unbestimmt.","Nach einer Präposition steht der Genitiv (-in), nicht der Akkusativ (-an)."],["هُوَ steht für männliche Wörter; السَّاعَةُ ist weiblich (ة).","أَنَا heißt „ich“.","هَذَا heißt „dies“ und ist männlich."],["هِيَ steht für weibliche Wörter; الْكِتَابُ ist männlich.","أَنْتَ heißt „du“.","هَذِهِ heißt „diese“ (weiblich)."],["Weibliche Eigennamen haben kein Tanwīn (sie sind Diptota).","Im Nominativ steht Ḍamma, nicht Fatḥa – und ohne Tanwīn.","Eigennamen sind schon bestimmt und bekommen keinen Artikel."],["مَرْفُوعٌ ist der Nominativ.","مَنْصُوبٌ ist der Akkusativ.","مَبْنِيٌّ heißt „unveränderlich“, das ist kein Fall."]],"i":[["Khabar ist der ganze Ausdruck عَلَى الْمَكْتَبِ; الْمَكْتَبِ selbst hat -i, nicht -u.","Hier regiert die Präposition عَلَى den Genitiv, kein vorangehendes Nomen (keine Iḍāfa).","Es gibt kein Verb, also kein Objekt; die Endung ist -i."],["عَلَى ist kein Nomen, sondern eine Präposition.","عَلَى ist kein Verb.","عَلَى ist eine Partikel und hat keine Fallendung."],["Pronomen verändern sich nicht (mabnī); هُوَ hat keine Ḍamma-Endung als Fallzeichen.","Vor هُوَ steht keine Präposition; es steht an Subjektstelle.","هُوَ ist ein Pronomen, keine Präposition."]]},
"m04a": {"q":[["Vor الْ wird مِنْ zu مِنَ, und nach مِنْ steht der Genitiv, nicht -u.","Vor الْ spricht man مِنَ (mit a), und der Genitiv endet auf -i, nicht -a.","إِلَى heißt „zu, nach“, nicht „aus“."],["„kam vom Markt“ wäre جَاءَ … مِنَ السُّوقِ; ذَهَبَ heißt „ging“.","Der Satz hat ein Verb (ذَهَبَ): „ging“, nicht „ist“.","Bilāl ist das Subjekt (Fāʿil), nicht Begleiter; „mit“ wäre مَعَ."],["أَنْتِ (mit i) ist die Form für eine Frau.","أَنَا heißt „ich“.","هُوَ heißt „er“."],["Mubtadaʾ ist das Subjekt des Nominalsatzes (ohne Verb vorne).","Khabar ist das Prädikat des Nominalsatzes.","Muḍāf ist das erste Glied einer Genitivverbindung."]],"i":[["Das Perfekt hat keinen Fall; es ist mabnī, nicht marfūʿ.","ذَهَبَ ist ein Verb, keine Präposition.","Ein Mubtadaʾ ist ein Nomen; ذَهَبَ ist ein Verb."],["Das Verb steht vorne – also Verbalsatz, und das Subjekt heißt Fāʿil, nicht Mubtadaʾ.","بِلَالٌ ist der Handelnde, nicht das Objekt; die Endung ist -un.","Vor بِلَالٌ steht keine Präposition; die Endung ist -un."],["Der Fāʿil ist الْمُدَرِّسُ; الْفَصْلِ hat -i.","Hier regiert die Präposition مِنْ, kein vorangehendes Nomen.","Es ist ein Verbalsatz; ein Khabar gibt es hier nicht, und die Endung ist -i."]]},
"m05": {"q":[["Der Muḍāf darf keinen Artikel haben.","Der Muḍāf verliert sein Tanwīn.","Der Muḍāf ilaihi steht im Genitiv (-i), nicht im Nominativ."],["بَيْتُ الْإِمَامِ ist richtig: Muḍāf ohne al, Muḍāf ilaihi im Genitiv.","بَيْتُ حَامِدٍ ist richtig: Eigennamen als Muḍāf ilaihi im Genitiv mit -in.","قَلَمُ الطَّالِبِ ist richtig gebildet."],["-u hat der Muḍāf, wenn er Subjekt ist – nicht der Muḍāf ilaihi.","Der Muḍāf ilaihi steht nie im Akkusativ.","Der Muḍāf ilaihi hat immer eine Genitivendung."],["Nach يَا steht beim Eigennamen Ḍamma ohne Tanwīn.","Der Munādā-Eigenname endet auf -u, nicht auf -i.","Eigennamen bekommen keinen Artikel, auch nicht nach يَا."],["مَنْ muss als Besitzer hinter كِتَابُ stehen: كِتَابُ مَنْ.","مَنْ ist unveränderlich und bekommt kein Tanwīn.","مَا fragt „was“; nach dem Besitzer fragt man mit مَنْ."],["„auf“ ist عَلَى.","„vor“ ist أَمَامَ.","„hinter“ ist خَلْفَ."]],"i":[["بِلَالٍ hat -in (Genitiv); Khabar ist كِتَابُ.","Vor بِلَالٍ steht keine Präposition, sondern das Nomen كِتَابُ.","Ein Naʿt beschreibt; بِلَالٍ ist der Besitzer."],["Mubtadaʾ ist هَذَا.","كِتَابُ steht vorne in der Iḍāfa (Muḍāf) und im Nominativ.","Es gibt kein Verb, also kein Objekt; die Endung ist -u."],["Es gibt kein Verb, also keinen Fāʿil.","Nach يَا steht ein Munādā, kein Satzsubjekt.","Es gibt kein Mubtadaʾ, zu dem بِلَالُ das Prädikat wäre."],["تَحْتَ ist ein Ẓarf (Nomen), keine Präposition.","الْمَكْتَبِ hat -i; Khabar ist تَحْتَ الْمَكْتَبِ.","Mubtadaʾ ist الْقِطُّ."]]},
"m06": {"q":[["هَذَا ist männlich; بِنْتٌ ist weiblich.","ذَلِكَ ist männlich (und fern).","هُوَ heißt „er“."],["Das Wort ist unbestimmt; es braucht Tanwīn (-tun).","Das ة wird als runde Tāʾ geschrieben, nicht als ت.","طَالِبَاتٌ ist der Plural „Studentinnen“."],["رَأْسٌ (Kopf) ist männlich.","أَنْفٌ (Nase) ist männlich.","فَمٌ (Mund) ist männlich."],["„Wer ist das?“ ist مَنْ هَذَا؟","„Was ist das?“ ist مَا هَذَا؟","„Wo ist das?“ ist أَيْنَ هَذَا؟"],["جِدًّا steht nicht vor dem Adjektiv.","جِدًّا verstärkt ein Adjektiv und steht hinter ihm, nicht am Satzanfang.","جِدًّا gehört zum Adjektiv, nicht zu هَذَا."],["Das Alif von الْ fällt nach لِـ weg: لِلْ.","Nach لِـ steht der Genitiv (-i).","Die Präposition heißt لِـ (mit i) und wird angehängt."]],"i":[["Das Prädikat ist der ganze Ausdruck لِبِلَالٍ, بِلَالٍ selbst hat -in.","بِلَالٍ steht nach der Präposition لِـ, nicht nach einem Nomen.","Es gibt kein Verb, also kein Objekt."],["هَذِهِ ist unveränderlich (mabnī) und hat kein Ḍamma als Fallzeichen.","Khabar ist مُدَرِّسَةٌ; هَذِهِ ist das Subjekt.","Vor هَذِهِ steht keine Präposition."]]},
"m07": {"q":[["ذَلِكَ ist männlich; نَاقَةٌ ist weiblich (ة).","هَذِهِ zeigt auf Nahes, gesucht ist „fern“.","هَذَا ist männlich und nah."],["تِلْكَ ist weiblich; مُؤَذِّنٌ ist männlich.","هَذِهِ ist weiblich und nah.","هِيَ heißt „sie“, kein Demonstrativ."],["Die weibliche Form von هَذَا ist هَذِهِ (nah).","تِلْكَ ist Singular; der Plural „jene“ wäre أُولَئِكَ.","تِلْكَ zeigt auf etwas, es ist keine Präposition."]],"i":[["Mubtadaʾ ist تِلْكَ, das Demonstrativ am Anfang.","Ein Naʿt müsste bestimmt sein; nach einem Demonstrativ ist das unbestimmte Wort das Prädikat.","Vor مُمَرِّضَةٌ steht keine Präposition; die Endung ist -un."]]},
"m08": {"q":[["„Das ist ein Buch“ wäre هَذَا كِتَابٌ – unbestimmt, ohne الْ.","„Das ist das Buch“ bräuchte ein Pronomen dazwischen: هَذَا هُوَ الْكِتَابُ.","„Wessen Buch?“ ist كِتَابُ مَنْ؟"],["هَذِهِ سَاعَةٌ جَمِيلَةٌ heißt „Das ist eine schöne Uhr.“","السَّاعَةُ ist weiblich: هَذِهِ und جَمِيلَةٌ, nicht هَذَا und جَمِيلٌ.","Das Demonstrativ steht vor dem Nomen, nicht dahinter."],["الْمَسْجِدُ ändert seine Endung (-u, -a, -i).","الْبَيْتُ ändert seine Endung (-u, -a, -i).","السَّاعَةُ ändert seine Endung (-u, -a, -i)."],["Nach خَلْفَ steht der Genitiv (-i), nicht -u.","أَمَامَ heißt „vor“, nicht „hinter“.","خَلْفَ steht als Ortsangabe im Akkusativ (-a), nicht -u."]],"i":[["Das Prädikat ist جَدِيدٌ; الْكِتَابُ hat den Artikel und gehört zu هَذَا („dieses Buch“).","Vor الْكِتَابُ steht kein Muḍāf; es hat -u, nicht -i.","Es gibt kein Verb, also kein Objekt."],["Ein Naʿt müsste bestimmt sein wie الْكِتَابُ; جَدِيدٌ ist unbestimmt → Prädikat.","Badal ist الْكِتَابُ; جَدِيدٌ ist die Aussage.","Mubtadaʾ ist هَذَا; جَدِيدٌ kommt am Ende."],["أَمَامَ ist ein Nomen (Ẓarf) mit Fatḥa, keine Präposition.","أَمَامَ sagt, wo er saß; es ist keine Person oder Sache, auf die die Handlung fällt.","Es ist ein Verbalsatz; ein Khabar gibt es nicht, und die Endung ist -a."]]},
"m09": {"q":[["Das Adjektiv steht hinter dem Nomen, nicht davor.","Das ist ein Satz: „Das Buch ist neu.“","Nomen und Adjektiv müssen in der Bestimmtheit übereinstimmen: unbestimmt + unbestimmt."],["Beide bestimmt = „das neue Auto“ – kein Satz.","Beide unbestimmt = „ein neues Auto“ – kein Satz.","Das heißt „dieses neue Auto“ – es fehlt das Prädikat."],["Nach بَيْتٍ (Genitiv) steht auch das Adjektiv im Genitiv (-in), nicht -un.","بَيْتٍ ist unbestimmt; das Adjektiv darf dann kein الْ haben.","بَيْتٌ ist männlich; das Adjektiv braucht kein ة."],["جَمِيلٌ hat Tanwīn (-un).","كَبِيرٌ hat Tanwīn (-un).","مَرِيضٌ hat Tanwīn (-un)."],["الْبِنْتُ صَغِيرَةٌ ist ein Satz: „Das Mädchen ist klein.“","Das Adjektiv muss weiblich sein wie الْبِنْتُ: الصَّغِيرَةُ.","Nomen und Adjektiv müssen beide bestimmt sein."],["„dieser“ ist هَذَا.","„jener“ ist ذَلِكَ.","„wer?“ ist مَنْ."]],"i":[["Das Prädikat ist بَيْتٌ جَدِيدٌ; جَدِيدٌ beschreibt بَيْتٌ (beide unbestimmt).","Mubtadaʾ ist هَذَا.","جَدِيدٌ hat -un; vor ihm steht kein Muḍāf."],["Die Präposition فِي regiert بَيْتٍ; جَدِيدٍ steht im Genitiv, weil es بَيْتٍ beschreibt.","Die Endung ist -in, nicht -un; das Prädikat ist فِي بَيْتٍ.","Vor جَدِيدٍ steht kein Muḍāf: بَيْتٍ hat Tanwīn."],["الْجَدِيدُ ist bestimmt wie الْبَيْتُ, also Adjektiv; das Prädikat ist جَمِيلٌ.","Ein zweites Mubtadaʾ gibt es hier nicht; الْجَدِيدُ beschreibt الْبَيْتُ.","Ein Adjektiv, das mit seinem Nomen übereinstimmt, ist Naʿt, keine Apposition."],["جَوْعَانُ ist Diptot (faʿlān) und hat kein Tanwīn, also nur eine Ḍamma.","Ein Naʿt müsste bestimmt sein wie الْوَلَدُ.","Das Khabar steht im Nominativ; die Endung ist -u."]]},
"m10": {"q":[["كِتَابُكَ heißt „dein Buch“.","كِتَابُهُ heißt „sein Buch“.","كِتَابُهَا heißt „ihr Buch“."],["أَبٌ gehört zu den fünf Nomen: Mit Pronomen bekommt es ein langes ū: أَبُوهُ.","Im Nominativ steht و, nicht ي.","Ein Wort mit Besitzendung bekommt keinen Artikel."],["بَيْتُهُ heißt „sein Haus“.","بَيْتُكَ heißt „dein Haus“.","بَيْتُهُمْ heißt „ihr Haus“ von mehreren."],["Bei Verwandten verwendet man لِـ, nicht عِنْدَ.","Bei Verwandten verwendet man لِـ, und die Präposition steht vorne.","أَنَا أَخٌ heißt „Ich bin ein Bruder“."],["ذَهَبْتَ (-ta) heißt „du gingst“.","ذَهَبَ heißt „er ging“.","ذَهَبَتْ heißt „sie ging“."],["Bei einem Stift (trennbarer Besitz) verwendet man عِنْدَ, nicht لِـ.","أَقَلَمُكَ؟ heißt „Ist das dein Stift?“","Der Satz hat zwei Subjekte; „einen Stift“ steht nur einmal und unbestimmt."]],"i":[["Vor dem ي der 1. Person kann keine Ḍamma stehen; sie ist nur gedacht (muqaddara).","كِتَابِي steht am Satzanfang ohne Präposition; das -ī ist das Pronomen „mein“.","Das Prädikat ist فِي الْحَقِيبَةِ; كِتَابِي ist das Subjekt."],["أَبٌ gehört zu den fünf Nomen: Nominativzeichen ist das و, nicht die Ḍamma.","Das Prädikat ist تَاجِرٌ; أَبُوكَ ist das Subjekt.","Es gibt kein Verb, also keinen Fāʿil."],["Vor dem -tu endet das Verb auf Sukūn (dhahab-tu), nicht auf Fatḥa.","ذَهَبْتُ ist Perfekt, nicht Präsens.","ذَهَبْتُ ist ein Verb, kein Nomen."]]},
"m11": {"q":[["-u hat das Subjekt, nicht das Objekt.","-i steht nach Präpositionen und im Muḍāf ilaihi.","Das Objekt hat eine Fallendung: -a."],["Das Objekt steht im Akkusativ (-a), nicht -u.","Das Objekt steht im Akkusativ (-a), nicht im Genitiv.","„den Gesandten“ ist bestimmt (الْ) und im Akkusativ."],["Objekt und Adjektiv stehen im Akkusativ, nicht im Nominativ.","Das Adjektiv folgt dem Objekt auch im Fall: -a, nicht -u.","Das Nomen muss bestimmt sein wie sein Adjektiv."],["Für männlichen Bezug heißt es فِيهِ.","„in ihm“ ist فِيهِ.","„hier“ ist هُنَا."],["Nach مَا mit هَذَا wird es kein korrekter Satz; vor Verben fragt man mit مَاذَا.","مَنْ fragt nach Personen: „Wen liebst du?“","أُحِبُّ ist „ich liebe“; gefragt ist „du“ (تُحِبُّ)."]],"i":[["Das Subjekt („ich“) steckt im Verb; الرَّسُولَ hat -a.","Es ist ein Verbalsatz; ein Khabar gibt es nicht.","Vor الرَّسُولَ steht keine Präposition; die Endung ist -a."],["أُحِبُّ ist Präsens (أُ-Präfix), nicht Perfekt.","أُحِبُّ ist ein Verb, kein Nomen.","Die Befehlsform wäre أَحْبِبْ; أُحِبُّ heißt „ich liebe“."],["Ein Verb hat hier nur ein Objekt (اللُّغَةَ); الْعَرَبِيَّةَ beschreibt es.","Vor الْعَرَبِيَّةَ steht kein Muḍāf: اللُّغَةَ hat den Artikel.","Es ist ein Verbalsatz; das Wort hat -a."]]},
"m12": {"q":[["بَيْتُكَ (-ka) sagt man zu einem Mann.","بَيْتُهَا heißt „ihr Haus“.","بَيْتِي heißt „mein Haus“."],["ذَهَبْتَ heißt „du (m.) gingst“.","ذَهَبْتِ heißt „du (w.) gingst“.","ذَهَبُوا heißt „sie (Plural) gingen“."],["Vor الْ kann kein Sukūn stehen; das -t bekommt eine Kasra als Hilfsvokal.","ذَهَبْتُ heißt „ich ging“ – passt nicht zu الْبِنْتُ.","Bei einem weiblichen Subjekt braucht das Verb das -t: ذَهَبَتْ."],["الَّذِي ist männlich; السَّيَّارَةُ ist weiblich.","مَنْ fragt nach Personen und ist hier kein Relativwort.","هَذِهِ heißt „diese“, kein Relativpronomen."],["Das beantwortet „Woher kommst du?“","Auf „Wie geht es dir?“ antwortet man nicht mit „ja“.","Das beantwortet „Wohin?“"]],"i":[["Das Verb steht vorne: Verbalsatz, also Fāʿil statt Mubtadaʾ.","مَرْيَمُ ist diejenige, die geht, nicht das Objekt; die Endung ist -u.","Es ist ein Verbalsatz; ein Khabar gibt es nicht."],["Das -t mit Sukūn ist nur das Zeichen für weiblich; der Fāʿil ist مَرْيَمُ.","ذَهَبَتْ ist Perfekt.","ذَهَبَتْ ist ein Verb."]]},
"m13": {"q":[["مُسْلِمَاتٌ ist der Plural von مُسْلِمَةٌ (Musliminnen).","Diese Pluralform gibt es von مُسْلِمٌ nicht; es bildet den gesunden Plural.","مُسْلِمَانِ ist der Dual: „zwei Muslime“."],["مُدَرِّسُونَ ist der Plural von مُدَرِّسٌ (Lehrer).","مَدَارِسُ ist der Plural von مَدْرَسَةٌ (Schulen).","مُدَرِّسَتَانِ ist der Dual: „zwei Lehrerinnen“."],["كِتَابٌ hat einen gebrochenen Plural, keinen auf -āt.","Der Plural auf -ūna gilt nur für männliche Personen.","Diese Form gibt es nicht; das Muster ist fuʿul: كُتُبٌ."],["Diese Form gibt es nicht; das Muster ist afʿāl.","قَلَمٌ hat einen gebrochenen Plural, keinen auf -āt.","Diese Form gibt es nicht."],["هُوَ ist Singular.","هُنَّ ist für weibliche Personen; مُدَرِّسُونَ sind Männer.","هِيَ ist Singular weiblich (oder Sachplural)."],["ذَهَبُوا heißt „sie (Männer) gingen“.","ذَهَبَتْ heißt „sie (eine Frau) ging“.","ذَهَبْنَا (langes ā) heißt „wir gingen“."],["أُولَئِكَ ist „jene“ (fern).","هَذَانِ ist der Dual „diese zwei“.","هُمْ heißt „sie“, kein Demonstrativ."]],"i":[["Beim gesunden männlichen Plural ist das Nominativzeichen das و, nicht die Ḍamma.","Das Khabar steht im Nominativ; ي wäre Akkusativ oder Genitiv.","Mubtadaʾ ist هُمْ; مُدَرِّسُونَ ist die Aussage."],["Der weibliche Plural hat kein و; das Zeichen ist die Ḍamma.","Das Khabar steht im Nominativ, nicht im Akkusativ.","Nach einem Demonstrativ ist das unbestimmte Wort das Prädikat, nicht ein Adjektiv."],["Vor dem و (sie) endet das Verb auf Ḍamma: dhahab-ū.","ذَهَبُوا ist Perfekt; ein nūn gibt es hier nicht.","ذَهَبُوا ist ein Verb, kein Nomen."]]},
"m14": {"q":[["بَيْتُكُمْ heißt „euer Haus“.","بَيْتُهُمْ heißt „ihr Haus“ (mehrere).","بَيْتِي heißt „mein Haus“."],["ذَهَبْنَ (kurzes a) heißt „sie (Frauen) gingen“.","ذَهَبْتُمْ heißt „ihr gingt“.","ذَهَبُوا heißt „sie (Männer) gingen“."],["مُحَمَّدٌ ist arabisch und hat Tanwīn.","نُوحٌ ist fremd, aber kurz (drei Buchstaben) und hat Tanwīn.","بِلَالٌ ist arabisch und hat Tanwīn."],["In der Iḍāfa darf zwischen Muḍāf und Muḍāf ilaihi nichts stehen, und der Muḍāf hat kein الْ.","Das Adjektiv darf die Iḍāfa nicht trennen; es kommt ans Ende.","Der Muḍāf verliert sein Tanwīn, und das Adjektiv steht am Ende und ist bestimmt."],["Nach مِنْ steht أَيِّ im Genitiv (-i), nicht -u.","Hier fehlt مِنْ („aus“), und بَلَدٍ muss als Muḍāf ilaihi im Genitiv stehen.","Nach أَيِّ steht das Nomen unbestimmt."]],"i":[["Das Prädikat ist هَذَا; بَيْتٍ hat -in.","Vor بَيْتٍ steht keine Präposition, sondern أَيُّ als Muḍāf.","بَيْتٍ beschreibt nichts; es ist das zweite Glied der Iḍāfa."],["Mubtadaʾ ist اللَّهُ.","Ein Naʿt müsste mit اللَّهُ übereinstimmen und beschreiben; رَبُّنَا ist die Aussage „unser Herr“.","Es gibt kein Verb, also kein Objekt; die Endung ist -u."]]},
"m15": {"q":[["بَيْتُكُمْ ist „euer Haus“ zu Männern.","بَيْتُهُنَّ heißt „ihr Haus“ (Frauen, 3. Person).","بَيْتُكِ ist „dein Haus“ zu einer Frau."],["بَعْدَ ist Muḍāf; das Folgende steht im Genitiv, nicht -u.","Das Folgende steht im Genitiv, nicht im Akkusativ.","Das Folgende hat die Genitivendung -i."],["„er ging hinaus“ ist خَرَجَ.","„er saß“ ist جَلَسَ.","„er ging“ ist ذَهَبَ."],["ذَهَبْتُنَّ ist „ihr (Frauen) gingt“.","ذَهَبْنَا heißt „wir gingen“.","ذَهَبُوا heißt „sie gingen“."]],"i":[["بَعْدَ ist ein Nomen (Ẓarf) mit Fatḥa, keine Präposition.","بَعْدَ sagt, wann; auf es fällt keine Handlung.","Es ist ein Verbalsatz; die Endung ist -a."],["Vor الصَّلَاةِ steht keine Präposition, sondern das Nomen بَعْدَ.","Die Endung ist -i; ein Objekt hätte -a.","Der Fāʿil ist das -tu in رَجَعْتُ."]]},
"m16": {"q":[["هَؤُلَاءِ steht nur für Personen.","Sachplurale behandelt man wie weiblichen Singular, nicht wie männlichen.","أُولَئِكَ steht für (ferne) Personen."],["Sachplurale bekommen das Adjektiv im weiblichen Singular, keinen Plural.","Das Adjektiv muss weiblich sein.","Der Plural auf -ūna gilt nur für männliche Personen."],["Bei Tieren (nicht vernunftbegabt) steht das Verb weiblich: خَرَجَتْ.","Das Verb vor dem Subjekt steht immer im Singular, und Tiere zählen weiblich.","Das Verb vor dem Subjekt steht im Singular."],["مَسْجِدٌ hat einen gebrochenen Plural, keinen auf -āt.","Der Plural auf -ūna gilt nur für männliche Personen.","Diese Form gibt es nicht; das Muster ist mafāʿil."],["هُمْ steht für männliche Personen.","Sachplurale behandelt man weiblich: هِيَ.","هُنَّ steht für weibliche Personen, nicht für Sachen."]],"i":[["Das Prädikat ist كُتُبٌ; جَدِيدَةٌ beschreibt كُتُبٌ.","Mubtadaʾ ist هَذِهِ.","كُتُبٌ hat Tanwīn und ist daher kein Muḍāf; جَدِيدَةٌ hat -un."],["Das Verb steht vorne: Verbalsatz, also Fāʿil.","Die Hunde gehen selbst hinaus; die Endung ist -u.","Es ist ein Verbalsatz; ein Khabar gibt es nicht."]]},
"m17": {"q":[["Sachplural → Adjektiv weiblich: mit ة.","Sachplurale bekommen ein Adjektiv im Singular, keinen gebrochenen Plural.","Der Plural auf -ūna gilt nur für männliche Personen."],["قَمِيصٌ hat einen gebrochenen Plural, keinen auf -āt.","Diese Form gibt es im Buch nicht.","Diese Form gibt es im Buch nicht."],["حِمَارَاتٌ gibt es nicht.","أَحْمِرَةٌ kommt im Buch nicht vor.","Der Plural auf -ūna gilt nur für männliche Personen."],["هَؤُلَاءِ steht nur für Personen.","هَذَا ist männlich; Sachplurale behandelt man weiblich.","هَذَانِ ist der Dual („diese zwei“)."]],"i":[["الْقُمْصَانُ ist bestimmt, رَخِيصَةٌ unbestimmt – also Aussage, kein Adjektiv.","Mubtadaʾ ist الْقُمْصَانُ.","Vor رَخِيصَةٌ steht kein Muḍāf; الْقُمْصَانُ hat den Artikel."],["Das Prädikat ist مُدِيرُ; الشَّرِكَةِ hat -i.","الشَّرِكَةِ beschreibt nicht, sondern ist der Besitzer („der Firma“).","Es gibt kein Verb, also kein Objekt; die Endung ist -i."]]},
"m18": {"q":[["بُيُوتٌ ist der Plural „Häuser“.","بَيْتَيْنِ ist der Dual im Akkusativ/Genitiv.","Der Plural auf -ūna gilt nur für männliche Personen."],["Das ة wird vor der Endung zu ت: سَيَّارَتَانِ.","سَيَّارَاتٌ ist der Plural „Autos“.","Das ة darf nicht wegfallen; es wird zu ت."],["هَذَانِ ist der männliche Dual.","هَؤُلَاءِ ist der Plural.","هُمَا heißt „sie beide“, kein Demonstrativ."],["هُمْ ist Plural (drei und mehr).","هُنَّ ist weiblicher Plural.","هَذَانِ heißt „diese zwei“, kein Pronomen."],["أَخٌ bildet den Dual mit و: أَخَوَانِ.","إِخْوَةٌ ist der Plural „Brüder“.","Diese Form gibt es nicht."],["Nach كَمْ steht kein Plural.","Nach كَمْ steht kein Plural, und der Fall ist Akkusativ.","Nach كَمْ steht der Singular."],["Nach كَمْ steht der Singular, nicht der Plural.","Das Nomen nach كَمْ steht im Akkusativ (-an), nicht -un.","Nach كَمْ steht kein Dual."],["قَلَمًا bekommt ein Alif.","بَيْتًا bekommt ein Alif.","كِتَابًا bekommt ein Alif."],["Das Adjektiv muss im Dual stehen wie طَالِبَانِ.","جُدُدٌ ist Plural; gebraucht wird der Dual.","طَالِبَانِ sind männlich; das Adjektiv braucht kein ة."]],"i":[["Beim Dual ist das Nominativzeichen das Alif, nicht die Ḍamma.","Mubtadaʾ ist هَذَانِ.","Nach einem Demonstrativ ist das unbestimmte Wort das Prädikat."],["Das Wort beschreibt طَالِبَانِ und steht im Nominativ (-āni), nicht im Akkusativ.","Vor جَدِيدَانِ steht kein Muḍāf; die Endung ist -āni.","Mubtadaʾ ist هُمَا."],["قَلَمًا ist kein Objekt eines Verbs, sondern präzisiert كَمْ.","Das Khabar ist عِنْدَكَ; قَلَمًا hat -an.","Vor قَلَمًا steht kein Muḍāf; die Endung ist -an."],["كَمْ ist ein Nomen (Fragewort), keine Partikel – es hat eine Stelle im Satz.","كَمْ ist unveränderlich (mabnī); das Khabar ist عِنْدَكَ.","Es gibt kein Verb, also kein Objekt."]]},
"m19": {"q":[["كِتَابٌ ist männlich, also braucht die Zahl ein ة (umgekehrte Übereinstimmung).","Die Zahl steht vorne und ist Muḍāf; das Gezählte folgt im Genitiv.","Nach 3–10 steht das Gezählte im Plural, nicht im Singular."],["وَاحِدٌ ist ein Adjektiv und steht hinter dem Nomen, nicht als Muḍāf davor.","وَاحِدٌ steht hinter dem Nomen.","كِتَابٌ ist männlich, also وَاحِدٌ ohne ة."],["Akkusativ Singular steht nach كَمْ und ab 11, nicht nach 3–10.","Das Gezählte ist Muḍāf ilaihi und steht im Genitiv.","Nach 3–10 steht der Plural."],["Die Zahl ist Objekt von رَأَيْتُ und steht im Akkusativ (-a), nicht -u.","رِجَالٌ ist männlich; die Zahl braucht ein ة.","Das Gezählte ist Muḍāf ilaihi und steht im Genitiv (-in), nicht -an."],["Nach فِي steht die Zahl im Genitiv (-i).","بَيْتٌ ist männlich; die Zahl braucht ein ة.","Die Zahl steht vor dem Gezählten, nicht als Adjektiv dahinter."],["هُوَ fehlt nicht; der Satz ist ohne vollständig.","Gefragt ist nicht nach dem Ding, sondern nach der Zahl der Geldstücke (رِيَالًا).","Nach كَمْ steht normalerweise ein Tamyīz; hier ist er nur weggelassen."],["Personen dieses Musters bilden hier den gebrochenen Plural رُكَّابٌ.","Diese Form gibt es nicht.","رُكُوبٌ ist ein Maṣdar: „das Reiten, Fahren“."],["قُدَمَاءُ gibt es auch, im Buch steht aber قُدَامَى.","Der Plural auf -ūna ist hier nicht die Buchform.","أَقْدَامٌ ist der Plural von قَدَمٌ (Fuß)."]],"i":[["Das Verb steht vorne: Verbalsatz, also Fāʿil statt Mubtadaʾ.","Die Studenten gehen selbst hinaus; die Endung ist -u.","Muḍāf ilaihi ist طُلَّابٍ; ثَلَاثَةُ steht vorne und hat -u."],["Der Fāʿil ist ثَلَاثَةُ; طُلَّابٍ hat -in.","طُلَّابٍ beschreibt nicht, sondern ist das Gezählte; die Endung ist -in.","Ein Tamyīz im Akkusativ steht erst ab 11; hier -in."],["Der Fāʿil ist das -tu in رَأَيْتُ.","Muḍāf ilaihi ist رِجَالٍ; خَمْسَةَ hat -a.","Es ist ein Verbalsatz; ein Khabar gibt es nicht."],["أَرْبَعَةِ steht nach der Präposition فِي, nicht nach einem Nomen.","Die Endung ist -i; es ist kein Satzsubjekt.","Es gibt kein Verb, also kein Objekt."],["وَاحِدٌ hat -un; كِتَابٌ hat Tanwīn und ist kein Muḍāf.","Ohne Subjekt davor ist وَاحِدٌ keine Aussage; es beschreibt كِتَابٌ.","Mubtadaʾ wäre das erste Wort."]]},
"m20": {"q":[["بِنْتٌ ist weiblich, also steht die Zahl ohne ة.","Die Zahl steht vor dem Gezählten.","Nach 3–10 steht das Gezählte im Plural."],["ابْنٌ ist männlich, also braucht die Zahl ein ة.","Nach 3–10 steht das Gezählte im Plural.","Die Zahl steht vor dem Gezählten; mit ة, weil ابْنٌ männlich ist."],["غُرْفَةٌ ist weiblich, also ثَمَانِي ohne ة.","Die Form ist ثَمَانِي, und das Gezählte steht im Plural.","ثَمَانِيَةُ gehört zu männlichem Gezählten, und das Gezählte muss Plural sein."],["عَشَرَةُ (mit Fatḥa und ة) gehört zu männlichem Gezählten.","عَشَرَ gibt es als Teil von 11–19, nicht allein für 10.","Diese Form gibt es nicht."],["أُخْتٌ ist weiblich: اثْنَتَانِ, nicht اثْنَانِ.","Die Zwei steht als Adjektiv hinter dem Dual, nicht als Muḍāf davor.","Das Adjektiv steht im Nominativ wie أُخْتَانِ (-āni), nicht -aini."],["طَالِبَةٌ ist weiblich, also سَبْعُ ohne ة.","Nach 3–10 steht das Gezählte im Plural.","طُلَّابٍ sind Studenten (männlich), nicht Studentinnen."],["Diese Form gibt es nicht.","Diese Form gibt es nicht.","Diese Form gibt es nicht; das Muster ist fuʿal."]],"i":[["Das vorangestellte Prädikat ist فِي الْبَيْتِ; ثَلَاثُ ist das Subjekt.","ثَلَاثُ hat -u; die Präposition gehört zu الْبَيْتِ.","Es gibt kein Verb, also kein Objekt."],["غُرَفٍ hat -in; es beschreibt nicht, sondern ist das Gezählte.","Nach 3–10 steht kein Tamyīz im Akkusativ, sondern der Muḍāf ilaihi im Genitiv.","Das Khabar ist فِي الْبَيْتِ; غُرَفٍ hat -in."],["Das Khabar ist لِي; وَاحِدَةٌ beschreibt أُخْتٌ.","أُخْتٌ hat Tanwīn und ist kein Muḍāf.","Mubtadaʾ ist أُخْتٌ."]]},
"m21": {"q":[["هَذَا heißt „dies“ (nah).","تِلْكَ ist weiblich („jene“).","هَذِهِ heißt „diese“ (weiblich, nah)."],["Diese Form gibt es nicht.","لَوْنٌ hat einen gebrochenen Plural, keinen auf -āt.","Diese Form gibt es nicht; das Muster ist afʿāl."],["نُحِبُّهَا heißt „Wir lieben sie“.","أُحِبُّهُ heißt „Ich liebe ihn“.","يُحِبُّنَا heißt „Er liebt uns“."],["قَلَمٌ ist männlich, also braucht die Zahl ein ة.","Nach 3–10 steht das Gezählte im Plural.","Die Zahl ist Muḍāf: ohne Tanwīn, und das Gezählte steht im Genitiv."],["هَؤُلَاءِ steht nur für Personen, und das Adjektiv muss weiblicher Singular sein.","Sachplurale bekommen das Adjektiv im weiblichen Singular: جَدِيدَةٌ.","Sachplurale behandelt man weiblich: هَذِهِ … جَدِيدَةٌ."]],"i":[["Das Prädikat ist بَيْتٌ; وَاسِعٌ beschreibt es (beide unbestimmt).","Mubtadaʾ ist ذَاكَ.","بَيْتٌ hat Tanwīn und ist kein Muḍāf."],["Das Khabar (bzw. Subjekt) ist لَوْنُ; سَيَّارَتِكَ ist der Besitzer.","Es gibt kein Verb, also kein Objekt.","سَيَّارَتِ beschreibt nicht, sondern ist das zweite Glied der Iḍāfa."],["Der Handelnde steckt im Verb (wir); الْمَدِينَةَ hat -a.","Das Khabar ist نُحِبُّ الْمَدِينَةَ als ganzer Satz; الْمَدِينَةَ hat -a.","Vor الْمَدِينَةَ steht keine Präposition."]]},
"m22": {"q":[["الْمَبْنِيُّ sind unveränderliche Wörter (z. B. هَذَا), keine Diptota.","الْمُثَنَّى ist der Dual.","الْمُضَافُ ist das erste Glied der Iḍāfa; es verliert das Tanwīn nur vorübergehend."],["مُحَمَّدٌ hat Tanwīn.","بِلَالٌ hat Tanwīn.","كِتَابٌ hat Tanwīn."],["زَيْنَبُ ist ein weiblicher Name → Diptoton.","مَسَاجِدُ hat das Pluralmuster mafāʿil → Diptoton.","أَصْدِقَاءُ hat das Muster afʿilāʾ → Diptoton."],["Farben nach dem Muster afʿal haben kein Tanwīn.","Mit الْ wäre es „der rote Stift“, kein Satz.","قَلَمٌ unbestimmt ergibt keinen Satz, und أَحْمَرُ hat kein Tanwīn."],["Das Muster mafāʿīl hat kein Tanwīn.","فِنْجَانٌ hat einen gebrochenen Plural.","Diese Form gibt es nicht."],["Diese Form steht so nicht im Buch; der gebrochene Plural ist دَقَائِقُ.","Diptota haben kein Tanwīn.","Diese Form gibt es nicht."],["عُثْمَانُ ist ein Männername.","عُثْمَانُ ist kein Plural.","عُثْمَانُ ist keine Farbe."],["لَنْدَنُ hat nicht das Muster afʿal.","لَنْدَنُ endet nicht auf ة.","لَنْدَنُ ist kein Plural."],["Auch im Singular fällt das Tanwīn so weg.","Tanwīn gibt es in allen drei Fällen (-un, -an, -in).","Doch: mit الْ, als Muḍāf und nach يَا."],["Die Reihenfolge ist vertauscht.","يَقُولُ/تَقُولُ ist Präsens: „er sagt – sie sagt“.","قُلْتُ/قُلْتِ heißt „ich sagte – du (w.) sagtest“."]],"i":[["Das Alif ist das Nominativzeichen des Duals; أَحْمَدُ hat Ḍamma.","Mubtadaʾ ist هَذَا.","Vor أَحْمَدُ steht kein Muḍāf, und es hat -u."],["الْقَلَمُ ist bestimmt, أَحْمَرُ unbestimmt – also Aussage, kein Adjektiv.","Mubtadaʾ ist الْقَلَمُ.","Es gibt kein Verb, also kein Objekt."],["Das Verb steht vorne: Verbalsatz, also Fāʿil statt Mubtadaʾ.","Āmina sagt selbst etwas; das Gesagte (شُكْرًا) ist das Objekt.","Es ist ein Verbalsatz; ein Khabar gibt es nicht."]]},
"m23": {"q":[["Diptota bekommen im Genitiv Fatḥa statt Kasra.","Diptota haben kein Tanwīn.","Nach مِنْ steht der Genitiv, nicht der Nominativ."],["Als Diptoton bekommt إِبْرَاهِيمَ im Genitiv Fatḥa, nicht Kasra.","Der Muḍāf verliert sein Tanwīn, und der Besitzer steht im Genitiv.","Diptota haben kein Tanwīn."],["مَسَاجِدُ ist Diptoton und hat kein Tanwīn.","مَسْجِدٌ ist männlich, also braucht die Zahl ein ة.","Ohne الْ und nicht als Muḍāf bekommt ein Diptoton im Genitiv Fatḥa."],["Mit الْ bekommt auch ein Diptoton wieder die Kasra.","„in den Moscheen“ ist bestimmt (الْ); und Diptota haben kein Tanwīn.","Nach فِي steht der Genitiv, nicht -u."],["Kasra bekommt ein Diptoton nur mit الْ oder als Muḍāf.","Diptota haben kein Tanwīn.","Ḍamma ist das Zeichen des Nominativs."],["مَكَّةُ ist ein weiblicher Eigenname (Diptoton): Genitiv mit Fatḥa.","Diptota haben kein Tanwīn.","Nach إِلَى steht der Genitiv."],["زُمَلَاءُ ist Diptoton und hat kein Tanwīn.","زَمِيلٌ ist männlich, also braucht die Zahl ein ة.","Nach 3–10 steht das Gezählte im Plural."]],"i":[["Die Fatḥa ist hier kein Akkusativ: Es gibt kein Verb, أَحْمَدَ ist der Besitzer.","Als Diptoton hat أَحْمَدَ im Genitiv Fatḥa, nicht Kasra.","أَحْمَدَ beschreibt nicht, sondern ist der Besitzer."],["Das Objekt ist الْقَلَمَ; إِبْرَاهِيمَ steht nach مِنْ.","Der Genitiv ist richtig, aber das Zeichen ist Fatḥa, nicht Kasra (Diptoton).","Vor إِبْرَاهِيمَ steht die Präposition مِنْ, kein Nomen."],["Nach 3–10 steht kein Tamyīz, sondern der Muḍāf ilaihi; die Fatḥa vertritt die Kasra.","مَسَاجِدَ beschreibt nicht, sondern ist das Gezählte; die Endung ist -a.","Es gibt kein Verb, also kein Objekt."],["Mit الْ gilt wieder die normale Kasra.","Es gibt kein Objekt: Beten ist intransitiv, الْمَسَاجِدِ steht nach فِي.","Vor الْمَسَاجِدِ steht die Präposition فِي, kein Nomen."],["Die Fatḥa ist hier das Genitivzeichen nach إِلَى, kein Akkusativ.","مَكَّةَ steht nach der Präposition إِلَى; es ist kein Ẓarf.","Der Genitiv ist richtig, aber als Diptoton mit Fatḥa, nicht Kasra."]]},
"b2-01": {"q":[["Nach إِنَّ steht das Subjekt im Akkusativ (-a), nicht -u.","Das Khabar von إِنَّ bleibt im Nominativ (-un), nicht -an.","Das Subjekt nach إِنَّ steht im Akkusativ, nicht im Genitiv."],["Nach إِنَّ kann kein selbstständiges Pronomen stehen; man hängt die Akkusativform an: إِنَّكَ.","Das Khabar bleibt im Nominativ: غَنِيٌّ.","Beides falsch: angehängtes Pronomen nötig, und das Khabar bleibt im Nominativ."],["Ismu inna ist das Subjekt (manṣūb), nicht das Prädikat.","Mit إِنَّ heißt das Prädikat nicht mehr Mubtadaʾ, sondern Khabar von inna.","Ein Objekt gibt es nur bei Verben; إِنَّ ist eine Partikel."],["„wahrlich“ drückt إِنَّ aus.","Fragen bildet man mit أَ oder هَلْ.","Verneinen tut man mit لَا, مَا oder لَيْسَ."],["ذُو hat kein Objekt; es ist Muḍāf.","Das Wort nach ذُو ist kein Prädikat, sondern Muḍāf ilaihi.","Das Wort nach ذُو steht immer im Genitiv, egal welchen Fall ذُو hat."],["ذَوُو ist der männliche Plural.","ذَوَاتُ ist der weibliche Plural.","ذِي ist der Genitiv von ذُو, nicht die weibliche Form."],["أَ muss direkt vor dem Erfragten stehen (مُدَرِّسٌ), nicht vor أَنْتَ.","In einer Entweder-oder-Frage heißt „oder“ أَمْ, nicht أَوْ, und die Frage beginnt mit أَ.","Die Frage beginnt mit أَ, nicht mit أَمْ."],["أَمْ steht nur in Fragen.","أَ ist die Fragepartikel.","لَعَلَّ heißt „vielleicht, hoffentlich“."],["Nach مِائَةٌ steht das Gezählte im Singular.","Das Gezählte ist Muḍāf ilaihi und steht im Genitiv (-in), nicht -an.","Das Gezählte steht unbestimmt im Singular."],["غَالٍ ist Prädikat und damit marfūʿ; das -in ist nur die verkürzte Form.","Vor غَالٍ steht kein Muḍāf; es ist das Prädikat.","Vor غَالٍ steht keine Präposition."]],"i":[["Nach إِنَّ heißt das Subjekt ismu inna und steht im Akkusativ, nicht Nominativ.","إِنَّ ist kein Verb; ein Objekt gibt es nicht.","Das Khabar ist جَدِيدٌ; الْمُدَرِّسَ hat -a."],["Ismu inna ist الْمُدَرِّسَ; جَدِيدٌ hat -un.","الْمُدَرِّسَ ist bestimmt, جَدِيدٌ unbestimmt – also Prädikat, kein Adjektiv.","Das Khabar von إِنَّ bleibt im Nominativ."],["Nach لَعَلَّ ist das Subjekt manṣūb (ismu laʿalla), nicht Mubtadaʾ.","لَعَلَّ ist kein Verb; ein Fāʿil gibt es nicht.","Das Khabar ist جَمِيلٌ; الْجَوَّ hat -a."],["Das Khabar ist ذُو عِلْمٍ; عِلْمٍ hat -in.","عِلْمٍ beschreibt nicht, sondern ist das zweite Glied nach ذُو.","ذُو ist ein Nomen, keine Präposition."],["ذُو gehört zu den fünf Nomen: Nominativzeichen ist das و, nicht die Ḍamma.","Mubtadaʾ ist بِلَالٌ.","ذُو sagt etwas über بِلَالٌ aus; ein Naʿt müsste bestimmt sein wie بِلَالٌ."]]},
"b2-02": {"q":[["„ist wirklich“ drückt إِنَّ aus.","„vielleicht“ ist لَعَلَّ.","„hat nicht“ wäre لَيْسَ لَهُ / لَيْسَ عِنْدَهُ."],["Das Subjekt nach لَيْسَ bleibt im Nominativ (-u), nicht -a.","Nach بِـ steht der Genitiv (-in), nicht -un.","بِـ gehört vor das Prädikat, nicht vor das Subjekt."],["لَسْتِ heißt „du (w.) bist nicht“.","لَيْسَا ist der Dual „sie beide sind nicht“.","لَسْنَ heißt „sie (Frauen) sind nicht“."],["السَّيَّارَةُ ist marfūʿ (Ism von laisa); die Kasra gehört zum Verb.","Weiblich ist das -t, nicht die Kasra; die Kasra ist nur Hilfsvokal.","Das ist richtig: Zwei Sukūn hintereinander werden durch Kasra getrennt."],["Das Prädikat ist schon eine Präposition (مِنَ); ein zweites بِـ davor ist unmöglich.","لَيْسَ passt sich an: „ich bin nicht“ = لَسْتُ, nicht لَيْسَ أَنَا.","بِالْهِنْدِ heißt „in Indien“, nicht „aus Indien“."],["مُهَنْدِسٍ gehört zum Prädikat (بِمُهَنْدِسٍ).","بِـ ist nur ein Zusatz vor dem Prädikat.","Doch: Das Subjekt ist das angehängte تُ."],["إِخْوَةٌ ist das Subjekt von لَيْسَ und bleibt im Nominativ.","لَسْتُ heißt „ich bin nicht“; gemeint ist „es gibt nicht“: لَيْسَ.","إِخْوَةٌ ist männlich; also لَيْسَ, nicht لَيْسَتْ."],["Das Khabar ist لِي; إِخْوَةً ist das Subjekt.","لِـ wirkt nur auf ـي, nicht auf إِخْوَةً.","Mit إِنَّ gibt es kein Mubtadaʾ mehr, sondern ismu inna (manṣūb)."],["ابْن ist Muḍāf (vor حَامِدٍ) und hat deshalb kein Tanwīn.","بِلَال bleibt im Fall des Satzes; nur das Tanwīn fällt weg.","Normalerweise schreibt man ابْن mit Alif; hier fällt es weg."]],"i":[["Das Prädikat ist بِجَدِيدٍ; الْبَيْتُ ist das Subjekt.","لَيْسَ ist ein unvollständiges Verb: Sein Subjekt heißt Ism, nicht Fāʿil.","Nach لَيْسَ heißt das Subjekt ismu laisa."],["جَدِيدٍ beschreibt nicht; es ist die Aussage.","Vor جَدِيدٍ steht kein Muḍāf, sondern das Zusatz-بِـ.","Das Khabar von لَيْسَ ist eigentlich manṣūb, hier in der Form Genitiv wegen بِـ."],["لَيْسَ ist unvollständig: Das تُ ist sein Ism, kein Fāʿil.","لَيْسَ ist ein Verb (mit Personalendung), keine Partikel.","لَسْتُ ist ein Verb, kein Nomen."],["Das Khabar ist لِي (vorangestellt); إِخْوَةً hat -an.","إِنَّ ist kein Verb; ein Objekt gibt es nicht.","Mit إِنَّ steht das Subjekt im Akkusativ, nicht im Nominativ."]]},
"b2-03": {"q":[["Das Muster afʿal hat kein Tanwīn.","Für „größer als“ braucht es die Form أَفْعَلُ, nicht طَوِيلٌ.","„als“ heißt مِنْ; ohne مِنْ bedeutet es „der Größte von …“."],["طُولَى (fuʿlā) steht nur mit الْ oder als Muḍāf, nicht mit مِنْ.","أَفْعَلُ mit مِنْ bleibt unverändert und bekommt kein ة.","أَطْوَلَتْ wäre ein Verb; es ist ein Adjektiv."],["„besser als“ bräuchte مِنْ; mit Genitiv danach ist es Superlativ.","„gut“ wäre حَسَنٌ.","„besser als“ bräuchte مِنْ vor dem Wort."],["Das Shadda hat nichts mit der Steigerung zu tun.","Das Shadda hat nichts mit weiblich zu tun.","Das ist Hochsprache: مِنْ + نِي wird immer مِنِّي."],["Nach لَكِنَّ steht das Subjekt im Akkusativ: حَامِدًا.","Das Khabar von لَكِنَّ bleibt im Nominativ; كَسْلَانُ ist außerdem Diptot.","Ohne Shadda (لَكِنْ) wirkt es nicht; dann bliebe حَامِدٌ im Nominativ."],["„aber“ ist لَكِنَّ.","„vielleicht, hoffentlich“ ist لَعَلَّ.","„wahrlich“ ist إِنَّ."],["طَالِبٌ ist männlich, also hat der erste Teil ein ة: ثَلَاثَةَ.","Bei 13–19 passt sich der zweite Teil dem Gezählten an: männlich → عَشَرَ.","Nach 11–19 steht das Gezählte im Singular im Akkusativ."],["طَالِبَةٌ ist weiblich: اثْنَتَا, nicht اثْنَا.","Bei 12 stimmen beide Teile überein: عَشْرَةَ.","Beide Teile müssen weiblich sein, und das Gezählte steht im Singular im Akkusativ."],["Plural im Genitiv steht nach 3–10.","Singular im Genitiv steht nach 100 und 1000.","Nach 11–99 steht der Singular."],["Auf eine verneinte Frage heißt نَعَمْ „ja, (ich bin es) nicht“.","لَا verneint.","كَلَّا heißt „keineswegs“."],["ثَلَاثَةٌ ist die Grundzahl „drei“.","ثُلُثٌ ist „ein Drittel“.","ثَالِثَةَ عَشَرَ ist „dreizehnter/dreizehnte“."]],"i":[["حَامِدٌ ist unbestimmt; أَطْوَلُ ist die Aussage, kein Adjektiv.","Mubtadaʾ ist حَامِدٌ.","Das Muster afʿal ist Diptot und hat kein Tanwīn."],["Nach لَكِنَّ heißt das Subjekt Ism von lākinna und ist manṣūb.","لَكِنَّ ist kein Verb; ein Objekt gibt es nicht.","Das Khabar ist كَسْلَانُ; حَامِدًا hat -an."],["Das Verb fehlt; رِيَالًا präzisiert die Zahl.","Nach 11–99 steht kein Muḍāf ilaihi, sondern ein Tamyīz im Akkusativ.","رِيَالًا beschreibt nichts, es ist das Gezählte."],["Im Superlativ steht das Nomen nach أَفْعَلُ im Genitiv (-in), nicht -an.","Das Khabar ist أَحْسَنُ; طَالِبٍ hat -in.","Vor طَالِبٍ steht keine Präposition, sondern أَحْسَنُ als Muḍāf."]]},
"b2-04": {"q":[["Das Subjekt ist آمِنَةُ; das تْ (mit Sukūn) ist nur ein Zeichen.","„du“ wäre ذَهَبْتَ/ذَهَبْتِ mit Vokal auf dem ت.","Ein Objekt wäre ein angehängtes Pronomen wie ـهُ, kein تْ."],["ذَهَبْنَ heißt „sie (Frauen) gingen“.","ذَهَبْتُمْ heißt „ihr gingt“.","ذَهَبَتْ heißt „sie (eine Frau) ging“."],["ذَهَبُوا heißt „sie (Männer) gingen“.","ذَهَبَتْ heißt „sie (eine Frau) ging“.","ذَهَبْتُنَّ heißt „ihr (Frauen) gingt“."],["„du (m.) gingst“ ist ذَهَبْتَ (-ta).","„sie ging“ ist ذَهَبَتْ (-at).","„wir gingen“ ist ذَهَبْنَا."],["Iʿrāb ist die Satzanalyse bzw. die Fallendungen.","Tanwīn ist das -un/-an/-in am Nomen.","Iḍāfa ist die Genitivverbindung."],["لَيْسَ verneint Nominalsätze, nicht das Perfekt.","لَا verneint das Präsens, nicht das Perfekt.","لَنْ verneint das Futur und steht vor dem Präsens."],["نَعَمْ auf eine verneinte Frage bestätigt die Verneinung – „ja, ich bin keiner“.","لَا mit „ich bin Muslim“ widerspricht sich.","Das hieße: „Ja, ich bin kein Muslim.“"],["الْجَوّ ist kein Objekt; es gibt kein Verb.","لِـ wirkt hier nicht auf الْجَوّ; dazwischen steht أَنَّ.","Es ist keine Frage, sondern eine Begründung („weil“)."],["Ein angehängtes Pronomen sieht man (z. B. -tu); hier ist nichts angehängt.","Das Subjekt ist kein Objekt.","In einem Verbalsatz gibt es kein Mubtadaʾ."]],"i":[["Vor dem و endet das Verb auf Ḍamma, und das و selbst ist der Fāʿil.","ذَهَبُوا ist Perfekt.","Das و ist hier kein „und“, sondern das Pronomen „sie“."],["Das Verb steht vorne: Verbalsatz, also Fāʿil.","Āmina geht selbst; die Endung ist -u.","Es ist ein Verbalsatz; ein Khabar gibt es nicht."],["Hier fragt مَا nicht; der Satz ist eine Aussage.","مَا heißt hier nicht „was“ (Relativ), sondern „nicht“.","مَا verneint nur; es ist kein Nomen."],["Ism von أَنَّ ist das ـهُ; مَرِيضٌ hat -un.","مَرِيضٌ ist die Aussage „krank“, beschreibt kein Nomen davor.","Der Fāʿil von ذَهَبَ ist إِبْرَاهِيمُ."]]},
"b2-05": {"q":[["Mubtadaʾ heißt das Subjekt des Nominalsatzes.","Das Objekt ist nicht das Subjekt.","Der Fāʿil steht im Nominativ, nicht im Akkusativ."],["Mit و am Verb gäbe es zwei Fāʿil; vor dem Fāʿil steht das Verb im Singular.","Der Fāʿil steht im Nominativ (-u).","ذَهَبْنَ ist für Frauen, und das Verb vor dem Fāʿil steht im Singular."],["Fāʿil ist nur ein Subjekt nach dem Verb; hier steht das Nomen vorne.","الطُّلَّابُ ist das Subjekt, kein Objekt.","Das Khabar ist ذَهَبُوا."],["Marfūʿ ist das Subjekt.","Majrūr steht nach Präpositionen und in der Iḍāfa.","Das Objekt hat eine Fallendung (-a)."],["Das Objekt steht im Akkusativ (-a), nicht -u.","Der Junge fragt – er ist Fāʿil (-u), nicht Objekt.","Das Objekt steht im Akkusativ, nicht im Genitiv."],["الْمَاءَ ist das Objekt (-a); das -i ist nur Hilfsvokal.","Das Kasra kommt nicht vom Namen, sondern trennt zwei Sukūn.","Das Verb hat damit nichts zu tun."],["Der erste Radikal hat im Perfekt immer Fatḥa.","Der dritte Radikal hat im Perfekt (3. Person m.) immer Fatḥa.","Doch: der zweite Radikal wechselt (fataḥa, shariba, karuma)."],["Das Objekt بِلَالًا steht im Akkusativ, nicht -un.","„ihn“ als Objekt wird angehängt (ـهُ), nicht als هُوَ.","Das Objekt steht im Akkusativ, nicht im Genitiv."]],"i":[["Der Fāʿil ist الْوَلَدُ; الْبَابَ hat -a.","Es ist ein Verbalsatz; ein Khabar gibt es nicht.","الْبَابَ beschreibt nicht, auf ihn fällt die Handlung."],["Das Verb steht vorne: Verbalsatz, also Fāʿil.","Der Junge öffnet; das Objekt ist الْبَابَ.","Es ist ein Verbalsatz; ein Khabar gibt es nicht."],["Das Verb steht vorne: Verbalsatz, also Fāʿil.","Es ist ein Verbalsatz; ein Khabar gibt es nicht.","Am Verb steht kein و; الطُّلَّابُ ist selbst der Fāʿil."],["Der Fāʿil ist الْوَلَدُ; أُمَّهُ hat -a.","Das ـهُ ist Besitzer („seine“), nicht Fāʿil.","أُمَّ selbst hat -a; nur das ـهُ ist Muḍāf ilaihi."]]},
"b2-06": {"q":[["„sie ging“ ist ذَهَبَتْ (-at).","„du (m.) gingst“ ist ذَهَبْتَ (-ta).","„ich ging“ ist ذَهَبْتُ (-tu)."],["طَالِبَةٌ ist weiblich; bei 11 sind beide Teile weiblich: إِحْدَى عَشْرَةَ.","Bei 11 passt auch der zweite Teil an: عَشْرَةَ.","Bei 11 passt auch der erste Teil an: إِحْدَى."],["Bei 13–19 hat der Einer das Gegenteil: weibliches Gezähltes → خَمْسَ ohne ة.","Der Zehner stimmt mit dem Gezählten überein: عَشْرَةَ.","Beide Teile sind hier falsch herum: خَمْسَ عَشْرَةَ."],["Nach أَيُّ steht kein Tamyīz, sondern der Muḍāf ilaihi.","Das Nomen nach أَيُّ ist kein Subjekt.","أَيُّ wechselt seinen Fall, das Nomen danach bleibt immer im Genitiv."],["Das Fragezeichen bestimmt keinen Fall.","Das Genus bestimmt nicht den Fall.","أَيُّ bekommt den Fall seiner Stellung: als Subjekt z. B. أَيُّ."],["Nach أَنَّ steht das Subjekt im Akkusativ: حَامِدًا.","Nach أَظُنُّ („ich glaube“) steht أَنَّ, nicht إِنَّ.","Das Khabar von أَنَّ bleibt im Nominativ: مَرِيضٌ."],["Nach قَالَ zitiert man die Rede mit إِنَّ, nicht أَنَّ.","لَعَلَّ heißt „hoffentlich“.","كَأَنَّ heißt „als ob“."],["Ein Pronomen „ihn“ wäre ـهُ mit Vokal; hier ist das h vokallos.","Das Femininzeichen ist ة, nicht ein vokalloses h.","Die Wurzel von لِمَ hat kein h."],["Adjektive auf -ān bilden das Femininum nach faʿlā, nicht mit ة.","جِيَاعٌ ist der Plural.","جَائِعَةٌ ist das Femininum eines anderen Wortes (جَائِعٌ)."],["هَاتُوا sagt man zu mehreren Männern.","هَاتِي sagt man zu einer Frau.","هَاتِ sagt man zu einem Mann."]],"i":[["أَنَّ ist eine Partikel; sein Nomen heißt Ism von anna, nicht Objekt.","Nach أَنَّ steht das Subjekt im Akkusativ.","Das Khabar ist مَرِيضٌ."],["أَيُّ hat -u; es ist kein Objekt.","خَرَجَ hat seinen Fāʿil im Pronomen; أَيُّ steht vorne und ist Mubtadaʾ.","Vor أَيُّ steht keine Präposition."],["أَيَّ hat -a: Es ist das vorangestellte Objekt.","Der Fāʿil ist das -ta in قَرَأْتَ.","أَيَّ fragt nach dem Ding, nicht nach Ort oder Zeit."],["Die Präposition بِـ regiert أَيِّ; قَلَمٍ folgt als Muḍāf ilaihi.","Das Objekt ist hier nicht قَلَمٍ; die Endung ist -in.","قَلَمٍ beschreibt nichts; es ist das zweite Glied nach أَيِّ."]]},
"b2-07": {"q":[["„ihr (f.) gingt“ ist ذَهَبْتُنَّ.","„wir gingen“ ist ذَهَبْنَا.","„sie (m.) gingen“ ist ذَهَبُوا."],["سَمِعُوا heißt „sie hörten“.","سَمِعْتُمْ heißt „ihr hörtet“.","لَيْسَ verneint keine Verben im Perfekt; dafür steht مَا."],["Das Genus des Objekts ändert den Vokal nicht; er richtet sich nach dem i davor.","Das ـهِ ist Objekt (manṣūb), nicht majrūr – nur der Laut passt sich an.","رَأَيْتِهِ ist richtig."],["Zwischen ـتُمْ und einem Objektpronomen muss ein و eingefügt werden.","Auch mit Ḍamma fehlt das و: -tumū-hu.","Die Endung für „ihr“ ist ـتُمْ, nicht ـتُو."],["Nach كَانَ bleibt das Subjekt im Nominativ, und das Prädikat wird manṣūb.","Das Prädikat von كَانَ steht im Akkusativ: مَرِيضًا.","Das Subjekt von كَانَ bleibt im Nominativ: بِلَالٌ."],["Eine Präpositionalgruppe bekommt keine Akkusativendung.","Die Gruppe ändert sich nicht; الْفَصْلِ bleibt im Genitiv nach فِي.","فِي bleibt; nur der Sinn ist jetzt Vergangenheit."],["ذُو kann keinen Artikel bekommen.","Ohne Artikel ist ذُو لِحْيَةٍ unbestimmt – passt nicht zu الرَّجُلُ als Adjektiv.","„der bärtige Mann“ ist bestimmt: الرَّجُلُ, nicht رَجُلٌ."],["Vor Hamzat al-waṣl bekommt das mīm Ḍamma, nicht Kasra.","Zwei vokallose Konsonanten hintereinander gehen nicht.","Der Hilfsvokal ist Ḍamma, nicht Fatḥa."],["„vier“ ist أَرْبَعَةٌ.","„vierter“ ist رَابِعٌ.","„vierzig“ ist أَرْبَعُونَ."]],"i":[["كَانَ ist ein unvollständiges Verb: Sein Subjekt heißt Ism, nicht Fāʿil.","Nach كَانَ gibt es kein Mubtadaʾ mehr, sondern ismu kāna.","Das Khabar ist مَرِيضًا."],["كَانَ hat kein Objekt; مَرِيضًا ist sein Prädikat.","Ein Ḥāl beschreibt einen Zustand neben einer Handlung; hier ist مَرِيضًا die Aussage selbst.","Ein Naʿt müsste mit بِلَالٌ im Fall übereinstimmen (-un)."],["Das و ist nur ein Bindelaut; der Fāʿil ist das تُمْ.","رَأَيْتُمُوهُ ist Perfekt.","Es ist keine Befehlsform."],["Das Khabar ist إِمَامٌ am Ende.","Ein zweites Mubtadaʾ gibt es nicht; ذُو beschreibt الرَّجُلُ.","Muḍāf ilaihi ist اللِّحْيَةِ; ذُو steht vorne (Muḍāf)."]]},
"b2-08": {"q":[["Das Subjekt ist sichtbar angehängt: ـنَا.","بَ gehört zur Wurzel ذ-ه-ب.","Doch: ـنَا ist der Fāʿil."],["ذَهَبْنَا (langes ā) heißt „wir gingen“.","ذَهَبْتُنَّ heißt „ihr (Frauen) gingt“.","ذَهَبَتْ heißt „sie (eine Frau) ging“."],["ذَهَبْتُمْ ist „ihr (Männer) gingt“.","ذَهَبْنَ ist „sie (Frauen) gingen“.","ذَهَبْتِ ist „du (w.) gingst“."],["Das تْ mit Sukūn ist nur das Femininzeichen.","Das Nomen davor wäre Mubtadaʾ, nicht Fāʿil.","Jedes Verb hat einen Fāʿil; hier ist er unsichtbar."],["Sukūn steht vor Endungen, die mit Konsonant beginnen (ـتُ، ـنَا).","Fatḥa hat nur die Grundform (ذَهَبَ).","Kasra kommt hier nicht vor."],["Fatḥa hat nur die 3. Person (ذَهَبَ).","Ḍamma steht nur vor dem و (ذَهَبُوا).","Kasra kommt hier nicht vor."],["أَكَلُوا heißt „sie haben gegessen“.","أَكَلْتُنَّ ist „ihr (Frauen)“.","أَكَلْنَا heißt „wir haben gegessen“."],["فَهِمَتْ heißt „sie hat verstanden“.","فَهِمْتَ ist „du (m.)“.","فَهِمْتُ heißt „ich habe verstanden“."]],"i":[["Vor ـنَا endet das Verb auf Sukūn, und ـنَا ist hier Subjekt („wir“), nicht Objekt.","ذَهَبْنَا ist Perfekt.","Das nūn der Frauen hat kein Alif; ذَهَبْنَا heißt „wir“."],["ـنَا (mit ā) wäre „wir“; hier ist es das nūn der Frauen.","Der Fāʿil ist sichtbar: das nūn.","Es ist keine Befehlsform."],["الْبَيْتِ steht nach مِنْ und ist kein Fāʿil.","Ohne Endung am Verb endet es auf Fatḥa, nicht Sukūn.","خَرَجَ ist ein Verb."]]},
"b2-09": {"q":[["Der feminine Plural hat im Akkusativ -i, nicht -a.","Das Objekt steht im Akkusativ, nicht im Nominativ.","Mit الْ gibt es kein Tanwīn, und das Zeichen ist -i."],["„mich“ braucht das Schutz-n: ـنِي.","„mich“ wird angehängt (ـنِي), nicht als أَنَا geschrieben.","سَأَلْتُ الْمُدَرِّسَ heißt „Ich fragte den Lehrer“."],["Das Subjekt ist das تَ; das n ist nur ein Schutzlaut.","Das n hat nichts mit Plural zu tun.","„uns“ wäre ـنَا."],["Nach مَا أَفْعَلَ steht das Nomen im Akkusativ, und أَفْعَلَ endet auf -a.","Staunen bildet man mit مَا أَفْعَلَ, nicht mit dem Adjektiv.","Staunen drückt man mit مَا aus, nicht mit كَمْ."],["Ḍamma bekommt nur ein Munādā, der kein Muḍāf ist (يَا بِلَالُ).","Nach يَا steht der Muḍāf im Akkusativ, nicht im Genitiv.","Der Muḍāf verliert sein Tanwīn."],["أَبُو ist Nominativ; nach يَا steht der Akkusativ.","أَبِي ist Genitiv (oder „mein Vater“).","Bei den fünf Nomen ist das Akkusativzeichen ein Alif: أَبَا."],["„womit?“ ist بِمَ.","„wovon?“ ist مِمَّ.","„warum?“ ist لِمَ."],["الَّذِينَ ist der männliche Plural.","اللَّتَانِ ist der weibliche Dual.","الَّذِي ist der männliche Singular."],["Zwei Alif hintereinander schreibt man als آ.","So ginge die Frage verloren; das Frage-أ bleibt als Madda.","Der Artikel darf nicht wegfallen."],["Das End-ى wird vor einem Pronomen zu ا, nicht zu ي.","Tanwīn und Pronomen schließen sich aus.","مَعْنِيهِ ist eine andere Form; das ى wird zu ا."],["Als Adjektiv steht die Zahl hinter dem Gezählten.","أَرْبَعَةُ الْكُتُبِ hieße eher „die vier von den Büchern“; gemeint ist die Zahl als Adjektiv.","كُتُبٌ ist männlich, also hat die Zahl ein ة."]],"i":[["Beim femininen Plural ist das Akkusativzeichen die Kasra, nicht die Fatḥa.","Vor السَّمَاوَاتِ steht keine Präposition; es ist das Objekt.","خَلَقَ ist ein Verb, kein Muḍāf."],["أَجْمَلَ hat -a und ist ein Verb des Staunens.","Im Staunen ist أَجْمَلَ ein erstarrtes Verb, kein Komparativ.","أَجْمَلَ ist ein Verb, kein Nomen."],["Mabnī auf Ḍamma ist nur ein Munādā ohne Iḍāfa (يَا بِلَالُ).","Nach يَا gibt es kein Verb, also kein Objekt.","Nach يَا steht ein Munādā, kein Mubtadaʾ."],["Das ي ist Objekt („mich“); der Fāʿil ist الْمُدَرِّسُ.","ـنِي ist das Objekt „mich“, nicht das Subjekt.","سَأَلَ ist Perfekt."]]},
"b2-10": {"q":[["ا und و sind keine Präfixe des Präsens.","م, ت, س sind nicht die Präsens-Vorsilben.","ب, ك, ل sind Präpositionen."],["Der Muḍāriʿ umfasst auch „gerade“ und die Zukunft.","„er schrieb“ ist كَتَبَ (Perfekt).","„schreib!“ ist اُكْتُبْ (Befehl)."],["Fatḥa hat die Vorsilbe (ya-), nicht der erste Radikal.","Ḍamma hat hier nur der zweite Radikal mancher Verben (yaktubu).","Kasra hat der erste Radikal im Muḍāriʿ nicht."],["كَتَبَ يَكْتُبُ gehört zur Gruppe a–u.","فَتَحَ يَفْتَحُ gehört zur Gruppe a–a.","فَهِمَ يَفْهَمُ gehört zur Gruppe i–a."],["شَرِبَ gehört zur Gruppe i–a: yašrabu.","شَرِبَ gehört zur Gruppe i–a, nicht a–u.","Das ist kein Muḍāriʿ des Grundstamms."],["فَتَحَ gehört zur Gruppe a–a (Kehllaut ح).","Das Präsens von فَتَحَ hat a, nicht i.","يُفَتِّحُ ist ein abgeleiteter Stamm (II) mit anderer Bedeutung."],["رَجُلٌ ist männlich, also braucht die Drei ein ة.","Einer und Zehner verbindet وَ, und der Einer hat Tanwīn.","Nach 21–99 steht das Gezählte im Singular."],["وَاحِدٌ hat Tanwīn.","ثَلَاثَةٌ hat Tanwīn.","تِسْعَةٌ hat Tanwīn."],["„nach“ wäre وَ (التَّاسِعَةُ وَالرُّبْعُ).","„halb neun“ ist الثَّامِنَةُ وَالنِّصْفُ.","„neun Uhr“ ist التَّاسِعَةُ allein."],["An وَ kann man kein Pronomen hängen; بَيْنَ muss wiederholt werden.","Nach بَيْنَ stehen keine selbstständigen Pronomen, sondern angehängte.","An وَ kann man kein Pronomen hängen."]],"i":[["يَكْتُبُ ist Präsens (Vorsilbe يَـ), nicht Perfekt.","Die Befehlsform wäre اُكْتُبْ.","يَكْتُبُ ist ein Verb."],["Es gibt kein Verb; رِيَالًا präzisiert die Zahl.","Nach 21–99 steht kein Muḍāf ilaihi, sondern ein Tamyīz im Akkusativ.","Das Khabar ist عِنْدِي."],["بَيْنَ ist ein Nomen (Ẓarf) mit Fatḥa, keine Präposition.","Auf بَيْنَ fällt keine Handlung; es gibt den Ort an.","Ein Ḥāl beschreibt einen Zustand; بَيْنَ gibt den Ort an."],["Vor بِلَالٍ steht keine Präposition, sondern das Nomen بَيْنَ.","Der Fāʿil ist حَامِدٌ.","Die Endung ist -in; ein Objekt hätte -an."]]},
"b2-11": {"q":[["يَذْهَبْنَ ist „sie (Frauen) gehen“.","تَذْهَبُونَ ist „ihr geht“.","ذَهَبُوا ist Perfekt: „sie gingen“."],["„ich gehe“ ist أَذْهَبُ.","„sie (Pl.) gehen“ ist يَذْهَبُونَ/يَذْهَبْنَ.","„er geht“ ist يَذْهَبُ."],["نَذْهَبُ heißt „wir gehen“.","تَذْهَبُ heißt „du gehst“ oder „sie geht“.","ذَهَبْتُ ist Perfekt: „ich ging“."],["يَدْرُسُونَ ist männlich.","تَدْرُسْنَ ist „ihr (Frauen) lernt“.","دَرَسْنَ ist Perfekt: „sie lernten“."],["Verneint wird mit لَا oder لَنْ, nicht mit سَـ.","Fragen bildet man mit أَ oder هَلْ.","سَـ steht vor dem Präsens und macht Futur, kein Perfekt."],["مَا verneint das Perfekt.","لَيْسَ verneint Nominalsätze.","سَـ macht Futur, es verneint nicht."],["جَالِسٌ ist das Partizip „sitzend“.","مَجْلِسٌ ist ein Ortsnomen: „Sitzplatz, Versammlung“.","يَجْلِسُ ist das Präsens „er sitzt“."],["Nach أَمَّا leitet فَـ die Aussage ein, nicht وَ.","ثُمَّ heißt „dann“, nicht die Antwort auf أَمَّا.","لَكِنَّ heißt „aber“."],["„mein Bruder“ ist أَخِي (bestimmt).","„meine Brüder“ ist إِخْوَتِي.","Das wäre لَيْسَ لِي أَخٌ."],["Vor أَ (ich) steht سَـ ohne Weiteres: سَأَذْهَبُ.","Vor يَـ steht سَـ: سَيَذْهَبُ.","Vor تَـ steht سَـ: سَتَذْهَبُ."]],"i":[["Bei den fünf Verben ist das Zeichen das nūn, nicht die Ḍamma.","يَدْرُسُونَ ist Präsens (يَـ … ونَ).","Ohne Partikel davor ist das Präsens marfūʿ."],["Es gibt kein Verb; الدُّخُولُ steht am Satzanfang.","الدُّخُولُ ist ein Maṣdar (Nomen), kein Verb.","Das Khabar ist مَمْنُوعٌ."],["أَمَّا fragt nicht.","أَمَّا verneint nicht.","أَمَّا verbindet nicht wie وَ; es teilt auf und verlangt فَـ."],["لَا des Verbots verlangt den Jussiv (لَا تَشْرَبْ); hier bleibt das Verb im Indikativ.","Das لَا, das eine ganze Gattung verneint, steht vor einem Nomen, nicht vor einem Verb.","لَا als Antwort („nein“) steht allein, nicht vor einem Verb."]]},
"b2-12": {"q":[["تَذْهَبْنَ heißt „ihr (Frauen) geht“.","تَذْهَبُ heißt „du (m.) gehst“ oder „sie geht“.","يَذْهَبْنَ heißt „sie (Frauen) gehen“."],["تَفْهَمِينَ ist „du (w.) verstehst“.","يَفْهَمْنَ ist „sie (Frauen) verstehen“.","تَفْهَمُونَ ist „ihr (Männer) versteht“."],["أَكْتُبُ heißt „ich schreibe“.","كَتَبْنَا ist Perfekt: „wir schrieben“.","تَكْتُبُونَ heißt „ihr schreibt“."],["Mafʿūl bihi wäre ein Objekt der Handlung; يَوْمَ gibt die Zeit an.","رَجَعَ hat kein Objekt; der Akkusativ kommt von der Zeitangabe.","Ein Ḥāl beschreibt einen Zustand, nicht die Zeit."],["Nach سَمِعْتُ steht أَنَّ, nicht إِنَّ.","Nach قَالَ steht إِنَّ, nicht أَنَّ.","Nach أَنَّ steht das Subjekt im Akkusativ: الِامْتِحَانَ."],["Dienstag ist الثُّلَاثَاءُ.","Mittwoch ist الْأَرْبِعَاءُ.","Freitag ist الْجُمُعَةُ."],["Montag ist الِاثْنَيْنِ.","Mittwoch ist الْأَرْبِعَاءُ.","Samstag ist السَّبْتُ."],["كُلَّ ist Zeitangabe und steht im Akkusativ, nicht -u.","Vor كُلَّ steht keine Präposition; es ist Zeitangabe im Akkusativ.","كُلَّ الْيَوْمِ heißt „den ganzen Tag“."]],"i":[["رَجَعَ hat kein Objekt; يَوْمَ gibt die Zeit an.","Ein Ḥāl beschreibt den Zustand von jemandem; يَوْمَ nennt die Zeit.","Der Fāʿil ist بِلَالٌ; يَوْمَ hat -a."],["صَبَاحًا ist nicht das, wohin man geht, sondern wann.","Ein Tamyīz präzisiert eine Zahl oder Menge; hier geht es um die Zeit.","صَبَاحًا beschreibt kein Nomen davor."],["Bei ـِينَ ist das nūn das Indikativzeichen, nicht die Ḍamma.","Das Subjekt ist das ي; das nūn ist nur das Zeichen.","Es ist eine Frage im Präsens, kein Befehl."],["Mit dem nūn der Frauen ist der Muḍāriʿ mabnī; das nūn ist Subjekt, kein Zeichen.","Die Vorsilbe تَـ zeigt das Präsens.","Mit dem nūn der Frauen gibt es keine Ḍamma am Verb."]]},
"b2-13": {"q":[["Das Indikativzeichen ist das ن, nicht das و.","Das و ist hier kein „und“, sondern das Pronomen „sie“.","Das و hat eine Funktion: Es ist das Subjekt."],["Der Fāʿil ist das و.","Das nūn der Frauen steht ohne و davor (يَذْهَبْنَ).","Ein Objekt wäre ein angehängtes Pronomen wie ـهُ."],["Bei يَذْهَبْنَ ist das nūn Subjekt, kein Indikativzeichen; das Verb ist mabnī.","„uns“ wäre ـنَا.","Das nūn ist das Subjekt (sie), nicht das Objekt."],["يَذْهَبُونَ heißt „sie gehen“.","تَذْهَبْنَ ist „ihr (Frauen) geht“.","ذَهَبْتُمْ ist Perfekt: „ihr gingt“."],["„ich“ (أَ) und „wir“ (نَ) haben verschiedene Vorsilben.","„er“ ist يَذْهَبُ, nicht تَذْهَبُ.","„du (f.)“ ist تَذْهَبِينَ, „ihr (f.)“ تَذْهَبْنَ."],["يَـ zeigt die Person (er), nicht den Fall.","Das Sukūn auf dem ersten Radikal gehört zum Muster, nicht zum Fall.","Doch: die Ḍamma am Ende."],["„Bus“ ist حَافِلَةٌ.","Gemeint ist das Fahrzeug, keine Firma.","„Lastwagen“ ist شَاحِنَةٌ."]],"i":[["Bei den fünf Verben ist das Zeichen das nūn, nicht die Ḍamma.","يَذْهَبُونَ ist Präsens.","Mabnī auf Sukūn ist das Präsens nur mit dem nūn der Frauen."],["Mit dem nūn der Frauen ist das Präsens mabnī; das nūn ist Subjekt.","يَذْهَبْنَ ist Präsens (Vorsilbe يَـ).","Mit dem nūn der Frauen gibt es keine Ḍamma am Verb."],["أَذْهَبُ ist Präsens (Vorsilbe أَ).","Die Befehlsform wäre اِذْهَبْ.","أَذْهَبُ ist ein Verb."]]},
"b2-14": {"q":[["Der Befehl kommt vom Präsens, nicht vom Perfekt.","Der Befehl ist eine Verbform, kein Maṣdar.","Der Befehl kommt nicht vom Partizip."],["Hat der zweite Radikal Ḍamma, bekommt das Hilfs-Alif auch Ḍamma: اُ.","Ein Wort kann nicht mit Sukūn beginnen; es braucht das Hilfs-Alif.","أَكْتُبُ heißt „ich schreibe“."],["Nur bei Ḍamma auf dem zweiten Radikal steht اُ; hier ist es Kasra.","Der Vokal des zweiten Radikals bleibt i (يَجْلِسُ).","Ein Wort kann nicht mit Sukūn beginnen."],["Der zweite Radikal hat a, also bekommt das Hilfs-Alif Kasra; der Vokal bleibt a.","Das Hilfs-Alif hat nie Fatḥa.","Ein Wort kann nicht mit Sukūn beginnen."],["أَكَلَ ist unregelmäßig: Der Befehl ist كُلْ.","أَكَلَ ist unregelmäßig: Der Befehl ist كُلْ.","Der Befehl endet auf Sukūn, und die Form ist كُلْ."],["Das Hilfs-Alif (u) fällt nach einem Wort weg.","بِلَالُ behält seine Ḍamma, und das Hilfs-Alif fällt weg.","Das Hilfs-Alif fällt weg; und es wäre u, nicht i."],["Zwei Sukūn hintereinander gehen nicht; das erste bekommt Kasra.","Der Befehl endet nicht auf Ḍamma.","Der Hilfsvokal ist Kasra, nicht Fatḥa."],["اُكْتُبُوا sagt man zu mehreren Männern.","اُكْتُبِي sagt man zu einer Frau.","تَكْتُبْنَ ist eine Aussage: „ihr schreibt“."],["Das Genus erlaubt kein unbestimmtes Mubtadaʾ.","Das Khabar ist فِي الْفَصْلِ, kein Verb.","Das ist erlaubt: Nach einer Fragepartikel darf das Mubtadaʾ unbestimmt sein."],["„aber“ ist لَكِنَّ.","„vielleicht“ ist لَعَلَّ.","„als ob“ ist كَأَنَّ."]],"i":[["Verben haben keinen Genitiv.","اُكْتُبْ ist ein Befehl, kein Perfekt.","Die Grundendung ist Sukūn; die Kasra kommt nur wegen des folgenden الْ."],["Bei der Plural-Form fällt das nūn weg; das ist das Zeichen, nicht Sukūn.","اُكْتُبُوا ist ein Befehl, kein Perfekt (das wäre كَتَبُوا).","Es ist ein Befehl; das nūn des Präsens fehlt."],["Das vorangestellte Khabar wäre فِي الْفَصْلِ; عَقْرَبٌ ist das Subjekt.","Es gibt kein Verb, also keinen Fāʿil.","Es gibt kein Verb, also kein Objekt."]]},
"b2-15": {"q":[["Mit Ḍamma ist es eine Aussage: „du gehst nicht“.","مَا verneint eine Aussage, es verbietet nicht.","Nach لَا steht der Muḍāriʿ, nicht der Befehl."],["„Geh nicht!“ wäre لَا تَذْهَبْ mit Sukūn.","„ich gehe nicht“ wäre لَا أَذْهَبُ.","„er ging nicht“ wäre مَا ذَهَبَ."],["Mit Ḍamma wäre es eine Aussage, kein Verbot.","Zwei Sukūn hintereinander gehen nicht; vor الْ wird Sukūn zu Kasra.","Fatḥa ist der Subjunktiv (nach أَنْ, لَنْ), nicht das Verbot."],["Nach dem verbietenden لَا fällt das nūn weg.","لَا تَذْهَبْنَ sagt man zu Frauen.","Nach لَا steht der Muḍāriʿ, nicht der Befehl."],["كَادَ heißt „beinahe“; er hat nicht gelacht.","Nicht verneint, sondern „beinahe“.","كَادَ ist Perfekt und bezieht sich auf die Vergangenheit."],["Doch: لَا = gewöhnlich, مَا = gerade jetzt.","Beide verneinen das Präsens, nicht Vergangenheit oder Zukunft.","Verbieten tut nur لَا mit Jussiv."],["Zwei Hamza (أَأْ) werden zu آ zusammengezogen.","أَكَلْتُ ist Perfekt: „ich aß“.","كُلْ ist der Befehl „iss!“."],["„wahrlich“ ist إِنَّ allein.","„vielleicht“ ist لَعَلَّ.","„weil“ ist لِأَنَّ."],["لَا النَّافِيَةُ verneint eine Aussage (Indikativ bleibt); hier steht Sukūn, also Verbot.","لَا الْعَاطِفَةُ verbindet Wörter („nicht …“), nicht vor einem Verb.","Das لَا der Gattung steht vor einem Nomen."]],"i":[["Nach dem verbietenden لَا steht der Jussiv (Sukūn), nicht der Indikativ.","Die Vorsilbe تَـ zeigt: Muḍāriʿ, kein Befehl.","تَجْلِسْ ist Präsens (Vorsilbe)."],["Nach dem verbietenden لَا fällt das nūn weg – es ist nicht da.","Die Vorsilbe تَـ zeigt: Muḍāriʿ, kein Befehl.","تَذْهَبُوا ist Präsens (Vorsilbe)."],["كَادَ wirkt wie كَانَ: Sein Nomen heißt Ism, nicht Fāʿil.","Der Junge lacht selbst; er ist kein Objekt.","Nach كَادَ heißt das Nomen ismu kāda."],["Nach كَادَ steht der Muḍāriʿ im Indikativ (Ḍamma), nicht im Subjunktiv.","Der Satz يَضْحَكُ ist das Prädikat von كَادَ, kein Zustand.","Nichts setzt das Verb in den Jussiv."]]},
"b2-16": {"q":[["Bei أَرَادَ (vier Buchstaben im Perfekt) hat die Vorsilbe Ḍamma, nicht Fatḥa.","أَرَدْتُ ist Perfekt: „ich wollte“.","يُرِيدُ heißt „er will“."],["رَادَ ist nicht das Perfekt von يُرِيدُ; dazu gehört أَرَادَ.","رَأَى heißt „er sah“.","Die Form gibt es nicht; das و der Wurzel wird zu ا: أَرَادَ."],["Hier wird nichts gefragt; der Satz ist eine Aussage.","Es heißt nicht „ich vergaß nicht“; مَا ist hier „das, was“.","Staunen wäre مَا أَفْعَلَ …!"],["ذُو muss dem Nomen im Fall folgen: طَالِبًا ist Akkusativ → ذَا.","ذِي ist der Genitiv; hier braucht es den Akkusativ ذَا.","ذَاتَ ist weiblich; طَالِبٌ ist männlich."],["عُمَرُ ist Diptot und hat kein Tanwīn.","Als Diptot bekommt عُمَرُ im Genitiv Fatḥa, nicht Kasra.","Nach إِلَى steht der Genitiv, nicht der Nominativ."],["Farbadjektive bilden das Femininum nach faʿlāʾ, nicht mit ة.","حُمْرٌ ist der Plural.","Das Muster ist faʿlāʾ (mit ء), nicht faʿlā."],["سَوْدَاوَاتٌ ist nicht der Plural der Farbe.","أَسَاوِدُ bedeutet „schwarze Schlangen“, nicht die Farbe im Plural.","سُودَانٌ ist der Name des Landes Sudan."],["Das stumme و fällt im Akkusativ weg; es steht nicht neben dem Alif.","عُمَرَ ist ein anderer Name (ʿUmar).","عَمْرٌو bekommt im Akkusativ Tanwīn mit Alif, nicht Fatḥa auf dem و."],["Ein Naʿt beschreibt eine Eigenschaft; الْحُسَيْنُ ist ein Name, der أَخُوكَ ersetzt.","Das Khabar ist أَيْنَ (vorangestellt).","Vor الْحُسَيْنُ steht kein Muḍāf; أَخُوكَ hat schon sein Pronomen."],["آخَرُ ist die männliche Form („ein anderer“). سُورَةٌ ist weiblich, also braucht es die weibliche Form أُخْرَى.","آخَرَةٌ gibt es nicht: Das Muster أَفْعَلُ bildet das Femininum nicht mit ة, sondern nach فُعْلَى → أُخْرَى. (Nicht verwechseln mit الْآخِرَةُ „das Jenseits“.)","أُخَرُ ist der Plural „andere“, z. B. سُوَرٌ أُخَرُ „andere Suren“; hier geht es um eine einzige Sure."],["„ein anderer Muslim“ wäre مُسْلِمٌ آخَرُ.","„ohne“ ist بِدُونِ / بِلَا.","„mehr als“ ist أَكْثَرُ مِنْ."],["قُرْآنٌ ist das Wort Allahs selbst; ein einzelnes Exemplar heißt مُصْحَفٌ.","كِتَابٌ ist jedes Buch.","سُورَةٌ ist ein Kapitel des Qurʾān."]],"i":[["Ein Naʿt beschreibt; الْحُسَيْنُ ist ein Name, der أَخُوكَ ersetzt.","Das Khabar ist أَيْنَ.","Es gibt kein Verb, also keinen Fāʿil."],["Ein Verb wie رَأَى hat hier nur ein Objekt; عَبَّاسًا ersetzt es.","Ein Ḥāl beschreibt einen Zustand; عَبَّاسًا ist ein Name.","Ein Tamyīz präzisiert Zahlen und Mengen."],["Nach إِلَى steht der Genitiv; die Fatḥa ist hier das Genitivzeichen.","Als Diptot hat عُمَرَ im Genitiv Fatḥa, nicht Kasra.","عُمَرَ ersetzt kein anderes Wort; es steht nach der Präposition."],["الشَّجَرَةُ ist bestimmt, خَضْرَاءُ unbestimmt – also Aussage, kein Adjektiv.","Das Muster faʿlāʾ ist Diptot und hat kein Tanwīn.","خَضْرَاءُ ersetzt nichts; es ist die Aussage."]]},
"b2-17": {"q":[["Nach أَنْ steht der Subjunktiv (-a), nicht -u.","Ohne أَنْ ist der Satz unvollständig: „ich will – ich gehe“.","Nach أَنْ steht hier kein Perfekt."],["لِـ ist hier nicht mit einem Objekt verbunden; أَفْهَمَ ist ein Verb.","Verben haben keinen Genitiv; لِـ ist hier „um zu“.","Das ist richtig: Nach „um zu“-لِـ steht der Subjunktiv."],["Nach أَنْ steht der Subjunktiv (-a), nicht -u.","Nach أَنْ steht hier kein Perfekt.","Ohne أَنْ und mit Sukūn stimmt es nicht; nötig ist أَنْ نَجْلِسَ."],["„soll ich“ wäre هَلْ أَجْلِسُ؟ oder أَأَجْلِسُ؟","Es ist eine Frage mit „kann“, keine Aussage.","„Setz dich!“ ist اِجْلِسْ."],["„bis“ ist حَتَّى / إِلَى.","„während“ ist أَثْنَاءَ.","„nach“ ist بَعْدَ."],["Bei einem weiblichen Lebewesen muss das Verb weiblich sein.","ذَهَبْنَ-Formen sind Plural; vor dem Fāʿil steht das Verb im Singular.","Vor dem Fāʿil steht das Verb im Singular, und hier weiblich."],["مَرْيَمُ ist eine Frau: Das Verb muss weiblich sein.","الْبَقَرَةُ ist ein weibliches Lebewesen.","آمِنَةُ ist eine Frau."],["سَمَحَ verlangt بِـ vor der Sache.","سَمَحَ steht mit لِـ vor der Person, nicht mit einem angehängten Objekt.","Die Präpositionen sind vertauscht: لِـ Person, بِـ Sache."],["„der Winter“ ist الشِّتَاءُ.","„der Frühling“ ist الرَّبِيعُ.","„der Sommer“ ist الصَّيْفُ."]],"i":[["Nach أَنْ steht der Subjunktiv, nicht der Indikativ.","أَذْهَبَ hat die Vorsilbe أَ: Präsens.","Die Endung ist -a (Subjunktiv), nicht Sukūn."],["Mit Shadda (أَنَّ) wäre es die Partikel wie إِنَّ; ohne Shadda setzt أَنْ Verben in den Subjunktiv.","أَنْ verneint nicht.","أَنْ ist eine Partikel, kein Pronomen."],["نَعْبُدَ ist ein Verb, kein Nomen; das لِـ bedeutet „um zu“.","Nach dem „um zu“-لِـ steht der Subjunktiv (-a).","نَعْبُدَ hat die Vorsilbe نَـ: Präsens, kein Befehl."],["Das تْ ist nur Femininzeichen; der Fāʿil ist آمِنَةُ.","دَخَلَتْ ist Perfekt.","دَخَلَتْ ist ein Verb."]]},
"b2-18": {"q":[["Nach أَنْ fällt das nūn weg.","تَشْرَبَ ist „du (m.)“ oder „sie“.","تَشْرَبْنَ ist „ihr (Frauen)“."],["Nach أَنْ fällt das nūn weg.","Das Subjekt ist „sie (Plural)“: يَخْرُجُوا.","Das erste Verb steht ohne Partikel und behält sein nūn."],["يَجْلِسْنَ bekommt kein Alif.","Das nūn der Frauen fällt nicht weg.","Das nūn der Frauen ist Subjekt und bleibt."],["Bei den fünf Verben ist das Zeichen das nūn, nicht die Ḍamma.","Das تَـ zeigt die Person (ihr).","Das و ist das Subjekt, kein Fallzeichen."],["كَـ steht nicht vor einem selbstständigen Pronomen.","An كَـ kann man kein Pronomen hängen.","مِنْ passt nicht; man sagt كَمِثْلِي."],["كُلّ folgt dem Objekt in den Akkusativ: كُلَّهُ.","In كُلَّ الْكِتَابِ steht das Nomen im Genitiv, nicht -a.","Das Pronomen muss zu الْكِتَابَ passen (männlich): ـهُ."],["Nach يَا steht kein Nomen mit Artikel direkt; man braucht أَيُّهَا.","Der Artikel steht vorne, nicht hinten.","يَا steht zuerst, dann أَيُّهَا."],["Das Muḍāf darf keinen Artikel haben: غُرْفَةُ النَّوْمِ.","Das Demonstrativ darf die Iḍāfa nicht trennen.","Das Muḍāf darf keinen Artikel haben."],["„wenn nicht“ ist إِلَّا (إِنْ لَا), anders geschrieben.","„bis“ ist إِلَى.","أَلَا („wohlan“) wird ohne Shadda geschrieben."],["آمِينَ ist kein Verb, es hat keine Personalendung.","آمِينَ ist kein Name.","آمِينَ ist keine Präposition."]],"i":[["يَخْرُجُوا hat die Vorsilbe يَـ: Präsens.","Nach أَنْ steht der Subjunktiv, nicht der Jussiv – beide verlieren das nūn, aber أَنْ macht Subjunktiv.","يَخْرُجُوا hat die Vorsilbe: kein Befehl."],["كُلُّهُمْ ersetzt الطُّلَّابُ nicht, sondern bekräftigt „alle“.","كُلّ ist keine Eigenschaft, sondern eine Bekräftigung.","Es gibt nur einen Fāʿil: الطُّلَّابُ."],["كَـ ist eine Präposition, kein Nomen.","الْمَسْجِدِ steht nach der Präposition كَـ, beschreibt aber nichts.","كَالْمَسْجِدِ ersetzt nichts; es ist die Aussage."],["Der Munādā ist أَيُّ; الرَّجُلُ folgt ihm mit Ḍamma.","Nach يَا gibt es kein Verb, also kein Objekt.","Es ist ein Anruf, kein Satz mit Aussage."]]},
"b2-19": {"q":[["لَمْ verneint die Vergangenheit.","مَا verneint das Perfekt (oder die Gegenwart).","لَيْسَ verneint Nominalsätze."],["Nach لَنْ fällt das Futur-سَـ weg.","Nach لَنْ steht der Subjunktiv (-a), nicht -u.","لَا verneint kein Futur mit سَـ; man sagt لَنْ أَذْهَبَ."],["Nach لَنْ fällt das nūn von تَذْهَبِينَ weg.","تَذْهَبَ ist „du (m.)“; gefragt ist die weibliche Form.","لَا verneint kein Futur mit سَـ; man verwendet لَنْ."],["Das nūn der Frauen ist Subjekt und fällt nie weg.","Es bleibt die weibliche Pluralform; تَدْرُسَ wäre Singular.","Die Form bekommt kein Alif."],["„Ich habe nie getrunken“ wäre مَا شَرِبْتُ قَطُّ.","„gerade nicht“ wäre مَا أَشْرَبُ.","„Trink nicht!“ ist لَا تَشْرَبْ."],["أَبَدًا verstärkt ein verneintes Futur.","جِدًّا heißt „sehr“.","فَقَطْ heißt „nur“."],["لَا أَذْهَبُ heißt „ich gehe nicht“.","لَنْ أَذْهَبَ heißt „ich werde nicht gehen“.","لَيْسَ verneint kein Verb im Perfekt."],["„der Letzte“ ist الْآخِرُ (männlich).","„die Zukunft“ ist الْمُسْتَقْبَلُ.","„die Welt, das Diesseits“ ist الدُّنْيَا."]],"i":[["Nach لَنْ steht der Subjunktiv, nicht der Indikativ.","Jussiv steht nach لَمْ, nicht nach لَنْ.","أَذْهَبَ hat die Vorsilbe أَ: Präsens."],["Nach لَنْ steht der Subjunktiv; Jussiv setzt لَمْ.","لَنْ verneint eine Aussage, es verbietet nicht.","لَنْ verneint, es bekräftigt nicht."],["Nach لَنْ fällt das nūn weg; das Verb ist nicht marfūʿ.","Die Vorsilbe تَـ zeigt: Präsens, kein Befehl.","تَذْهَبِي ist Präsens."],["أَبَدًا ist nicht das, was getrunken wird (das ist الْخَمْرَ).","Ein Ḥāl beschreibt einen Zustand; أَبَدًا gibt die Zeit an.","Ein Tamyīz präzisiert eine Zahl oder Menge."]]},
"b2-20": {"q":[["-āni ist der Nominativ des Duals.","-īna ist die Akk./Gen.-Endung des männlichen Plurals.","-ūna ist der Nominativ des männlichen Plurals."],["Das Objekt steht im Akkusativ: -aini, nicht -āni.","Das nūn des Duals hat Kasra, nicht Fatḥa.","Für „zwei“ reicht der Dual; ein Plural dazu ist falsch."],["Das Subjekt steht im Nominativ: -āni, nicht -aini.","Vor dem Fāʿil steht das Verb im Singular (جَاءَ).","Das Adjektiv folgt dem Subjekt in den Nominativ: -āni."],["Nach بَعْدَ steht der Genitiv: -aini.","Das nūn des Duals hat Kasra, nicht Fatḥa.","Für „zwei Tage“ nimmt man den Dual."],["أَحَدُهُمَا ist männlich; hier geht es um Weibliches.","Bei weiblichen Dingen braucht es الْأُخْرَى, nicht الْآخَرُ.","أَحَدُهُمَا passt nicht zu الْأُخْرَى; beide müssen weiblich sein."],["„Zwilling“ ist تَوْأَمٌ.","„Spiegel“ ist مِرْآةٌ.","„ein Mann mit Bart“ ist ذُو لِحْيَةٍ."],["Nach مِنْ steht der Genitiv: -aini.","Das nūn des Duals hat Kasra, nicht Fatḥa.","إِذَاعَاتٍ ist Plural (mehrere Sender), nicht „zwei“."]],"i":[["Beim Dual ist das Akkusativzeichen das ي, nicht die Fatḥa.","Vor كِتَابَيْنِ steht keine Präposition.","Der Fāʿil ist das -tu; كِتَابَيْنِ hat -aini (Akkusativ)."],["Beim Dual ist das Nominativzeichen das Alif, nicht die Ḍamma.","Das Verb steht vorne: Verbalsatz, also Fāʿil.","Die Lehrer kommen selbst; die Endung ist -āni."],["Das Ẓarf ist بَعْدَ; يَوْمَيْنِ folgt als Muḍāf ilaihi.","رَجَعَ hat kein Objekt.","Beim Dual ist das Genitivzeichen das ي, nicht die Kasra."],["Das Khabar ist لِي (vorangestellt).","Es gibt kein Verb, also keinen Fāʿil.","Es gibt kein Verb, also kein Objekt."]]},
"b2-21": {"q":[["„Er geht nicht“ ist لَا يَذْهَبُ.","„Er wird nicht gehen“ ist لَنْ يَذْهَبَ.","„Geh nicht!“ ist لَا تَذْهَبْ."],["Subjunktiv setzen أَنْ und لَنْ.","Nach لَمْ bleibt das Verb nicht im Indikativ.","Mabnī ist das Präsens nur mit nūn der Frauen."],["Im Jussiv fällt das nūn weg.","يَحْضُرْ ist Singular („er“); gefragt ist der Plural.","Nach لَمْ steht das Präsens, nicht das Perfekt."],["Vor الْ wird das Sukūn zu Kasra.","Nach لَمْ steht der Jussiv, nicht -u.","Nach لَمْ steht das Präsens, nicht das Perfekt."],["„als“ ist لَمَّا vor einem Perfekt; hier steht ein Jussiv.","„nicht mehr“ ist لَمْ يَعُدْ.","„niemals“ ist أَبَدًا / قَطُّ."],["Beide stehen mit dem Jussiv, nicht dem Subjunktiv.","لَمْ steht mit dem Präsens im Jussiv.","Doch: لَمَّا heißt „noch nicht“."],["قَبْلَ ist ein Nomen (Ẓarf).","لَيْسَ ist ein Verb.","هَذَا ist ein Nomen (Demonstrativ)."],["لَيْسَ wird konjugiert; das tun Partikeln nicht.","لَيْسَ hat Personalendungen wie ein Verb.","Pronomen sind هُوَ، أَنَا usw."],["وَلَا verneint auch das Buch.","مَا ist hier Verneinung, keine Frage.","Auch das Buch ist verneint."]],"i":[["Nach لَمْ steht der Jussiv.","Subjunktiv steht nach أَنْ/لَنْ, nicht nach لَمْ.","أَفْهَمْ hat die Vorsilbe أَ: Präsens."],["Subjunktiv setzt لَنْ; لَمْ setzt den Jussiv.","لَمْ verneint eine Aussage, es verbietet nicht.","لَمْ ist eine Partikel, kein Fragewort."],["Nach لَمْ steht der Jussiv, nicht der Subjunktiv.","يَحْضُرُوا hat die Vorsilbe: Präsens.","Es ist eine Aussage, kein Befehl."],["Verben haben keinen Genitiv; die Kasra ist nur Hilfsvokal vor الْ.","Die Vorsilbe أَ zeigt: Präsens, kein Befehl.","Nach لَمَّا steht der Jussiv, nicht der Indikativ."]]},
"b2-22": {"q":[["لَمْ، لَمَّا und das verbietende لَا setzen den Jussiv.","سَـ macht Futur, قَدْ bekräftigt; beide ändern die Endung nicht.","إِنَّ und أَنَّ stehen vor Nomen, nicht vor Verben."],["أَنْ und لَنْ setzen den Subjunktiv.","مَا und das verneinende لَا ändern die Endung nicht.","سَـ und سَوْفَ machen Futur und ändern die Endung nicht."],["Fatḥa ist das Zeichen des Subjunktivs.","Wegfall des nūn gilt nur für die fünf Verben (يَذْهَبُونَ …).","Kasra gibt es beim Verb nur als Hilfsvokal."],["Die fünf Verben haben keine Fatḥa am Ende; das nūn fällt weg.","Sukūn ist das Jussivzeichen einfacher Formen.","Das Alif am Ende ist nur Schreibung, nicht das Zeichen."],["يَذْهَبُونَ verliert im Subjunktiv und Jussiv das nūn.","تَذْهَبِينَ verliert im Subjunktiv und Jussiv das nūn.","نَذْهَبُ hat -u, -a oder Sukūn."],["لَنْ يَذْهَبُوا ist richtig (Subjunktiv).","لَمْ يَذْهَبُوا ist richtig (Jussiv).","أَنْ يَذْهَبُوا ist richtig (Subjunktiv)."],["Bei den fünf Verben gibt es keine Ḍamma am Ende.","Das ي ist das Subjekt „du (w.)“.","Das تَـ zeigt die Person."]],"i":[["Nach أَنْ steht der Subjunktiv, nicht der Jussiv – die Form sieht gleich aus.","Das nūn fehlt: Das Verb ist nicht marfūʿ.","Die Vorsilbe تَـ zeigt: Präsens, kein Befehl."],["Nach dem verbietenden لَا steht der Jussiv, nicht der Subjunktiv.","Das nūn fehlt: Das Verb ist nicht marfūʿ.","Die Vorsilbe تَـ zeigt: Präsens."],["Das nūn der Frauen fällt nie weg; die Form ist mabnī.","Nach لَمْ ist die Stelle majzūm, nicht marfūʿ.","Die Vorsilbe يَـ zeigt: Präsens."]]},
"b2-23": {"q":[["-ūna ist der Nominativ.","-aini ist der Dual.","-āti ist der weibliche Plural."],["Das Objekt steht im Akkusativ: -īna, nicht -ūna.","-aini wäre der Dual „zwei Lehrer“.","Das nūn des Plurals hat Fatḥa (-īna), nicht Kasra."],["Zusammengesetzte Zahlen sind 11–19.","الْمَعْدُودُ ist das Gezählte.","الْكُسُورُ sind die Brüche."],["Nach بِـ steht der Genitiv: -īna.","Nach 20 steht das Gezählte im Akkusativ, nicht im Genitiv.","Nach 20 steht das Gezählte im Singular."],["طَالِبَةٌ ist weiblich: إِحْدَى, nicht وَاحِدٌ.","Nach 21–99 steht das Gezählte im Singular.","Einer und Zehner verbindet وَ, und die Eins ist hier إِحْدَى."],["Bei weiblichem Gezählten hat der Einer kein ة.","Beide Teile haben den gleichen Fall; im Nominativ -ūna.","Einer und Zehner verbindet وَ, und der Einer hat Tanwīn."],["Ohne وَلَا fehlt das „noch“; es sind zwei unverbundene Sätze.","Nach لَمْ steht das Präsens (لَمْ يَقْرَأْ), nicht das Perfekt.","لَنْ verneint die Zukunft und steht mit dem Präsens."],["„für“ passt nicht; das Buch ist von Ibn Manẓūr.","„um zu“ steht vor Verben.","„weil“ ist لِأَنَّ."],["„bestehen“ ist نَجَحَ.","„lernen“ ist دَرَسَ.","„vergessen“ ist نَسِيَ."]],"i":[["Beim männlichen Plural ist das Akkusativzeichen das ي, nicht die Fatḥa.","Vor الْمُدَرِّسِينَ steht keine Präposition.","-īna ist Plural, nicht Dual (-aini)."],["Beim männlichen Plural ist das Nominativzeichen das و, nicht die Ḍamma.","Das Verb steht vorne: Verbalsatz, also Fāʿil.","Das Alif ist das Zeichen des Duals."],["Tamyīz ist كِتَابًا; عِشْرِينَ ist das Objekt.","Die Zehner haben im Akkusativ ي, keine Fatḥa.","عِشْرِينَ gibt keine Zeit oder keinen Ort an."],["Das Objekt ist عِشْرِينَ; كِتَابًا präzisiert es.","Nach 20 steht kein Muḍāf ilaihi, sondern ein Tamyīz im Akkusativ.","Ein Ḥāl beschreibt einen Zustand."]]},
"b2-24": {"q":[["Singular im Akkusativ steht nach 11–99.","Singular im Genitiv steht nach 100 und 1000.","Nach 3–10 steht der Plural im Genitiv, nicht im Akkusativ."],["Nach 100 und 1000 steht der Singular.","Akkusativ steht nach 11–99.","Nach 100 und 1000 steht kein Dual."],["Vor dem Gezählten (Muḍāf) fällt das nūn des Duals weg.","Das nūn fällt weg, und das Gezählte steht im Genitiv.","200 ist der Dual مِائَتَا, nicht „zwei hundert“."],["3–10 verändern ihre Endung.","Die Zehner werden wie der männliche Plural dekliniert.","مِائَة und أَلْف verändern ihre Endung."],["اثْنَا ist Nominativ; als Objekt braucht es den Akkusativ اثْنَيْ.","Bei 12 fällt das nūn weg: اثْنَيْ عَشَرَ.","Nach 11–99 steht das Gezählte im Singular."],["Nach بِـ steht ثَلَاث im Genitiv (-i), nicht -u.","Nach مِائَة steht das Gezählte im Genitiv (-in), nicht -an.","Nach 3 steht مِائَة im Singular (ثَلَاثُمِائَةٍ), und das Gezählte nach 100 im Singular."],["أَلْف ist männlich, also ثَلَاثَةُ, und das Gezählte nach 3 steht im Plural: آلَافِ.","Nach 3 steht der Plural آلَافِ, und als Muḍāf ohne Tanwīn.","آلَافِ ist Muḍāf (kein Tanwīn), und رِيَالٍ steht im Genitiv."],["Mit Gezähltem ist die Zahl Muḍāf und hat kein Tanwīn.","Doch: wenn das Gezählte fehlt.","Tanwīn gibt es in allen Fällen."],["سِتُّونَ ist der Nominativ.","سِتًّا ist die Zahl „sechs“, nicht „sechzig“.","Das nūn hat Fatḥa (-īna)."]],"i":[["Das vorangestellte Khabar ist عِنْدِي.","Tamyīz ist ein Akkusativ nach 11–99; خَمْسَةُ ist das Subjekt.","Es gibt kein Verb, also keinen Fāʿil."],["Nach 3–10 steht kein Tamyīz, sondern Muḍāf ilaihi.","رِيَالَاتٍ beschreibt nicht; es ist das Gezählte.","رِيَالَاتٍ ersetzt nichts; es folgt auf die Zahl als Muḍāf ilaihi."],["Das Objekt ist رِيَالَيْنِ; اثْنَيْنِ bekräftigt es als Adjektiv.","Ein Tamyīz steht nach 11–99; hier folgt „zwei“ als Adjektiv.","Vor اثْنَيْنِ steht kein Muḍāf: رِيَالَيْنِ hat sein nūn."],["Mubtadaʾ ist أُجْرَتُهُ.","Es gibt kein Verb, also kein Objekt.","Beim Dual ist das Nominativzeichen das Alif, nicht die Ḍamma."]]},
"b2-25": {"q":[["Marfūʿ bleibt der Ism von كَانَ, nicht das Khabar.","Majrūr steht nach Präpositionen und in der Iḍāfa.","Ein Khabar aus einem Wort ändert sich nach كَانَ: Es wird manṣūb."],["Der Ism von كَانَ bleibt im Nominativ, das Khabar wird manṣūb.","Das Khabar von كَانَ steht im Akkusativ: مَرِيضَةً.","Bei einem weiblichen Subjekt braucht كَانَ das -t: كَانَتْ."],["„nicht mehr“ wäre لَمْ يَعُدْ.","„nie“ wäre مَا … قَطُّ.","Das Präsens mit لَا يَزَالُ heißt „noch immer“, nicht „wird nicht“."],["Das Objekt steht im Akkusativ: أَبَا, nicht أَبُو.","أَبِي ist der Genitiv.","Bei den fünf Nomen braucht der Muḍāf den langen Vokal: أَبَا."],["Nach إِلَى steht der Genitiv: أَخِي, nicht أَخُو.","أَخَا ist der Akkusativ.","Bei den fünf Nomen braucht der Muḍāf den langen Vokal: أَخِي."],["قَبْلُ ist hier kein Subjekt; es steht nach مِنْ.","Das ist kein Fehler, sondern eine Regel.","Nach مِنْ stünde eigentlich Kasra; die Ḍamma kommt vom weggefallenen Muḍāf ilaihi."],["Im Buch steht der gebrochene Plural مَرْضَى.","أَمْرَاضٌ ist der Plural von مَرَضٌ „Krankheit“.","Diese Form gibt es nicht."],["Ein Khabar aus einem Wort wird manṣūb.","Der Ism bleibt zwar im Nominativ, gefragt ist aber das unveränderte Khabar.","Die Präpositionalgruppe bleibt unverändert."]],"i":[["Ein Ḥāl beschreibt einen Zustand neben einer Handlung; hier ist بَارِدًا die Aussage von كَانَ.","كَانَ hat kein Objekt.","Ein Naʿt müsste mit الْمَاءُ übereinstimmen (bestimmt, Nominativ)."],["لَا يَزَالُ ist ein unvollständiges Verb: Sein Nomen heißt Ism, nicht Fāʿil.","Nach لَا يَزَالُ gibt es kein Mubtadaʾ mehr.","بِلَالٌ hat -un; er ist kein Objekt."],["Bei den fünf Nomen ist das Akkusativzeichen das Alif, nicht die Fatḥa.","Der Fāʿil steckt in أَعْرِفُ (ich).","Muḍāf ilaihi ist das ـكَ, nicht أَبَا."],["Der Ism von كَانَ ist das unsichtbare „er“; قَبْلُ ist eine Zeitangabe.","قَبْلُ ist eine Zeitangabe, kein Handelnder.","Ohne Muḍāf ilaihi hat قَبْلُ nicht Kasra, sondern ist mabnī auf Ḍamma."]]},
"b2-26": {"q":[["أَجْوَفُ ist schwach am zweiten Radikal.","نَاقِصٌ ist schwach am dritten Radikal.","لَفِيفٌ hat zwei schwache Radikale."],["مِثَالٌ ist schwach am ersten Radikal.","نَاقِصٌ ist schwach am dritten Radikal.","مُضَعَّفٌ hat zweiten und dritten Radikal gleich (مَدَّ)."],["Beim Mithāl fällt das و im Präsens weg.","Die Vorsilbe hat Fatḥa, und das و fällt weg.","Der zweite Radikal hat Kasra: yazinu."],["وَضَعَ gehört zur Gruppe a–a (Kehllaut ع).","Das و fällt im Präsens weg.","Die Vorsilbe hat Fatḥa, nicht Ḍamma."],["Ein Hilfs-Alif braucht es nicht, weil زِ schon einen Vokal hat.","Das و ist weggefallen; die Form ist زِنْ.","تَزِنْ ist Präsens (Jussiv), kein Befehl."],["نُهَارٌ gibt es nicht; das Muster ist fuʿail.","أَنْهُرٌ ist ein Plural („Flüsse“).","Diese Form gibt es nicht."],["„nicht dürfen“ wäre يَجِبُ عَلَيْكَ أَلَّا تَرْجِعَ.","„nicht brauchen“ wäre لَا يَجِبُ عَلَيْكَ.","يَجِبُ + أَنْ + Präsens bezieht sich auf die Zukunft, nicht Vergangenheit."],["„nicht dürfen“ wäre يَجِبُ عَلَيْنَا أَلَّا نَحْضُرَ.","Die Verneinung لَا kehrt „müssen“ in „nicht müssen“ um.","Es ist Präsens, keine Vergangenheit."],["عَلَيْنَا ist eine Präpositionalgruppe, kein Subjekt.","الْقُرْآنَ ist das Objekt von نَفْهَمَ.","Das Subjekt ist sichtbar: der Ausdruck أَنْ نَفْهَمَ."],["„Wer ist das?“ ist مَنْ هَذَا؟","Hier wird nichts verneint.","„dort“ wäre هُنَاكَ."]],"i":[["يَقِفُ hat die Vorsilbe يَـ: Präsens.","Die Befehlsform wäre قِفْ.","يَقِفُ ist ein Verb."],["Das Perfekt wäre وَضَعَ.","Ohne Vorsilbe ist es kein Präsens, sondern Befehl.","ضَعِ ist ein echtes Verb (Befehl), kein Nomen mit Verbkraft."],["Nach أَنْ steht der Subjunktiv, nicht der Indikativ.","Das Objekt ist الْقُرْآنَ; نَفْهَمَ ist ein Verb.","Es ist ein Verbalsatz; ein Khabar gibt es nicht."],["Ein Ḥāl beschreibt einen Zustand; وُلَيْدًا ist das, was gesehen wurde.","Ein Tamyīz präzisiert Zahlen und Mengen.","Der Fāʿil ist das -tu in رَأَيْتُ."]]},
"b2-27": {"q":[["Mit و als erstem Radikal heißt das Verb Mithāl.","Schwach am dritten Radikal heißt Nāqiṣ.","Vier Radikale sind Rubāʿī."],["Vor einer Endung mit Konsonant fällt das Alif weg: qul-tu.","قَالَ gehört zur Gruppe a–u: Ḍamma, nicht Kasra.","Der schwache Radikal wird nicht als و geschrieben."],["سَارَ gehört zur Gruppe a–i: Kasra, nicht Ḍamma.","Vor einer Endung mit Konsonant fällt das Alif weg.","Der schwache Radikal wird nicht als ي geschrieben."],["Zwei Sukūn (و + ل) gehen nicht; das و fällt weg.","Nach لَمْ steht der Jussiv, nicht -u.","Nach لَمْ steht das Präsens, nicht das Perfekt."],["Ein Hilfs-Alif braucht es nicht, weil قُ einen Vokal hat.","Zwei Sukūn gehen nicht; das و fällt weg: قُلْ.","قَالْ ist keine Befehlsform."],["Vor der Endung -ū bleibt das Alif: نَامُوا.","Das Alif bleibt, und der Vokal ist a.","Ein Hilfs-Alif braucht es nicht."],["إِنَّ bekräftigt Nominalsätze, nicht ein Perfekt nach dem Schwur.","لَنْ verneint die Zukunft.","سَـ macht Futur."],["ظَنَّ hat zwei Objekte im Akkusativ; beides steht hier im Nominativ.","Auch das zweite Objekt steht im Akkusativ: جَمِيلًا.","Das erste Objekt steht im Akkusativ: الْجَوَّ."],["„du kannst nicht“ wäre لَا تَسْتَطِيعُ.","„du hast nicht gesagt“ wäre لَمْ تَقُلْ.","Es ist eine Verneinung, keine Aufforderung."],["Nach dem Schwur-و steht der Genitiv, nicht der Nominativ.","Nach dem Schwur-و steht der Genitiv, nicht der Akkusativ.","اللَّه hat eine Endung: -i nach وَ."]],"i":[["Die Vorsilbe يَـ zeigt: Präsens, kein Perfekt.","Die Vorsilbe zeigt: kein Befehl.","Nach لَمْ steht der Jussiv."],["Ein Ḥāl beschreibt einen Zustand zu einer Handlung; hier ist جَمِيلًا das zweite Objekt von ظَنَّ.","Ein Naʿt würde mit الْجَوَّ in Bestimmtheit übereinstimmen (الْجَمِيلَ).","Es gibt kein Mubtadaʾ; nach أَظُنُّ steht das Khabar im Akkusativ als Objekt."],["Das و ist hier der Schwur, keine Verbindung; اللَّهِ hat -i.","Ein Ḥāl-و leitet einen Zustandssatz ein; hier wird geschworen.","Das و ist eine Partikel, kein Pronomen."],["قُلْتُ hat die Endung -tu: Perfekt, kein Befehl.","Ohne Vorsilbe ist es kein Präsens.","قُلْتُ ist ein Verb."]]},
"b2-28": {"q":[["Schwach am ersten Radikal heißt Mithāl.","Schwach am zweiten Radikal heißt Ajwaf.","Jedes dieser Verben hat ein Perfekt (دَعَا، بَكَى)."],["Bei der Wurzel د-ع-و schreibt man ا, nicht ى; ى steht bei ي-Wurzeln (بَكَى).","Das و wird im Perfekt zu Alif.","So wird kein Perfekt geschrieben."],["Im Perfekt bleibt vor dem و das a: daʿau (دَعَوْا), nicht daʿū.","Das Alif fällt vor der Endung weg.","دَعَيْنَ ist keine Form von دَعَا."],["Das Alif fällt vor تْ weg.","بَكَى gehört zur Gruppe a–i (بَكَى يَبْكِي); das Perfekt hat a.","Der schwache Radikal fällt vor تْ weg."],["Die Wurzel ist د-ع-و: Das و kommt zurück, nicht ي.","Vor -tu kommt der Radikal zurück; das Alif steht nicht.","Der dritte Radikal darf nicht einfach fehlen."],["Nach لَنْ wird die Fatḥa auf dem ي gesprochen: yabkiya.","Den Buchstaben streicht nur der Jussiv (nach لَمْ).","يَبْكُوا ist Plural („sie“)."],["Im Jussiv fällt der schwache Radikal weg.","Der dritte Radikal fällt im Jussiv ganz weg.","Nach لَمْ steht das Präsens, nicht das Perfekt."],["Im Befehl fällt der schwache Radikal weg.","دَعَا gehört zur Gruppe a–u: اُدْعُ, nicht اِدْعِ.","دَعْ ist der Befehl eines anderen Verbs (وَدَعَ: „lass!“)."],["Im Jussiv fällt der schwache Radikal weg.","Im Präsens von رَأَى fällt das Hamza weg: تَرَى.","مَا تَرَى heißt „du siehst nicht“ (jetzt)."],["رَ ist die theoretische Form, wird aber nicht benutzt.","Diese Form gibt es nicht.","أَرِ ist der Befehl von أَرَى „zeigen“ („zeig!“)."],["„danach bügeln“ bräuchte سَـ und hieße سَأَكْوِيهِ بَعْدَ ذَلِكَ.","لَمْ verneint; es heißt „nicht“, nicht „danach“.","Es ist eine Aussage, kein Befehl."]],"i":[["Bei Nāqiṣ-Verben ist das Jussivzeichen der Wegfall des schwachen Buchstabens, nicht Sukūn.","Die Vorsilbe يَـ zeigt: Präsens, kein Befehl.","Die Vorsilbe يَـ zeigt: Präsens."],["Auf dem ي ist die Fatḥa sichtbar, nicht nur gedacht.","Nach لَنْ steht der Subjunktiv, nicht der Jussiv.","Nach لَنْ steht der Subjunktiv."],["Auf dem و wird die Ḍamma nicht gesprochen; sie ist nur gedacht.","Ein nūn gibt es nur bei den fünf Verben.","Die Vorsilbe يَـ zeigt: Präsens."],["Auf einem Alif kann man keine Fatḥa sprechen; sie ist nur gedacht.","Nach لَنْ steht der Subjunktiv; das Alif bleibt.","Die Vorsilbe يَـ zeigt: Präsens."]]},
"b2-29": {"q":[["Das ist ein Mithāl.","Das ist ein Nāqiṣ.","Das ist ein Mahmūz."],["Vor -tu werden die beiden gleichen Radikale getrennt: ḥajaj-tu.","Die Radikale müssen getrennt geschrieben werden, und der Vokal ist a.","حَجَّ hat kein ي."],["Wegen des Shadda kann der letzte Radikal kein Sukūn tragen; er bekommt Fatḥa.","Nach لَمْ ist diese Form mit Shadda und Ḍamma falsch.","Nach لَمْ steht das Präsens, nicht das Perfekt."],["Diese getrennte Form gibt es auch, im Buch gilt aber حُجَّ.","Der Befehl endet nicht auf Ḍamma.","Der Vokal ist u (يَحُجُّ), und im Buch ist es حُجَّ."],["„noch nicht“ heißt لَمَّا nur mit dem Jussiv.","„warum“ ist لِمَاذَا.","„nur“ ist إِنَّمَا / فَقَطْ."],["حَيْثُ heißt „wo“.","مُنْذُ heißt „seit“.","بَعْدَ heißt „nach“."],["أَبَدًا verstärkt ein verneintes Futur.","بَعْدُ heißt „noch (nicht)“.","فَقَطْ heißt „nur“."],["سَالِمٌ hat keinen schwachen Radikal und kein Hamza; سَأَلَ hat ein Hamza.","Ajwaf hat و oder ي als zweiten Radikal; hier ist es ein Hamza.","Nāqiṣ hat و oder ي als dritten Radikal."],["Mafrūq heißt getrennt (erster und dritter Radikal schwach).","Ajwaf hat nur einen schwachen Radikal.","Mithāl hat den ersten Radikal schwach."],["Das و fällt weg, und ein Hilfs-Alif braucht es nicht.","Im Befehl fällt auch das ي weg.","Das و fällt im Präsens und Befehl weg."],["Ohne وَ heißt es „kein Dank“.","مَا verneint Verben, nicht شُكْرًا.","لَيْسَ passt hier nicht."]],"i":[["Die Fatḥa ist kein Subjunktiv; nach لَمْ steht der Jussiv.","Die Vorsilbe zeigt: Präsens.","Die Vorsilbe zeigt: kein Befehl."],["Mit dem Perfekt heißt لَمَّا „als“; es verneint nicht.","لَمَّا verneint hier nicht.","لَمَّا fragt nicht."],["قَطُّ gibt die Zeit an, es ist kein Objekt.","قَطُّ beschreibt keinen Zustand.","Der Fāʿil ist das -tu in أَكْتُبْ."],["Das Perfekt wäre حَجَّ (mit a); حُجَّ mit u ist der Befehl.","Keine Vorsilbe: kein Präsens.","حُجَّ ist ein Verb."]]},
"b2-30": {"q":[["ذَهَبُوا ist Plural (drei und mehr).","ذَهَبَتَا ist der weibliche Dual.","ذَهَبْتُمَا heißt „ihr beide gingt“."],["ذَهَبَا ist der männliche Dual.","ذَهَبْنَ ist der weibliche Plural (drei und mehr).","ذَهَبْتُمَا heißt „ihr beide gingt“."],["يَذْهَبَانِ heißt „sie beide gehen“.","تَذْهَبُونَ heißt „ihr (alle) geht“.","Ohne nūn ist es Subjunktiv oder Jussiv; im Indikativ bleibt das nūn."],["Nach أَنْ fällt das nūn weg.","Vor dem Subjekt steht das Verb im Singular: يُرِيدُ.","يَذْهَبُوا ist Plural; gebraucht wird der Dual يَذْهَبَا."],["Das sind Perfektformen; die fünf Verben sind Präsensformen mit nūn.","Diese Formen haben kein nūn als Indikativzeichen.","Das sind Befehlsformen."],["Der Befehl hat kein nūn.","اِذْهَبُوا sagt man zu mehreren Männern.","تَذْهَبَا ist Präsens (Subjunktiv/Jussiv), kein Befehl."],["ـنَا ist „wir“ allgemein; eine eigene Dualform gibt es nicht.","ـتُمَا ist „ihr beide“.","ـَا ist „sie beide“."],["Was jeder nur einmal hat, steht bei zweien im Plural: أَسْمَاؤُ.","اسْمُكُمَا ist hier nicht die Buchform; man nimmt den Plural.","ـكُمْ ist „euer“ von mehreren; gefragt ist „ihr beide“: ـكُمَا."],["ـهُمْ ist „sie“ (Plural).","ـكُمَا ist „euch beide“.","ـهَا ist „sie“ (eine Frau)."]],"i":[["Bei den fünf Verben ist das Zeichen das nūn, nicht die Ḍamma.","Die Vorsilbe يَـ zeigt: Präsens.","Das nūn ist da: Das Verb ist marfūʿ, nicht manṣūb."],["Die Vorsilbe يَـ zeigt: Präsens.","Nach لَمْ steht der Jussiv, nicht der Subjunktiv.","Die Vorsilbe zeigt: kein Befehl."],["ذَهَبَا hat keine Vorsilbe: Perfekt.","Das Alif ist hier das Pronomen „die beiden“, also Subjekt.","ذَهَبَا ist ein Verb, kein Nomen."],["Beim Dual fällt das nūn weg; das ist das Zeichen, nicht Sukūn.","Es ist ein Befehl, kein Perfekt.","Ohne Vorsilbe: kein Präsens."]]},
"b2-31": {"q":[["Nicht nur im Fall, sondern in vier Punkten.","Auch in Bestimmtheit und Fall.","Das Naʿt stimmt in vier Punkten überein."],["Das Adjektiv folgt dem Objekt in den Akkusativ: -a, nicht -u.","Das Adjektiv muss bestimmt sein wie الْمُدَرِّسَ; unbestimmt wäre es ein Ḥāl („als neuer“).","Das Adjektiv folgt dem Objekt in den Akkusativ, nicht Genitiv."],["Das Adjektiv folgt dem Dual: كَبِيرَانِ.","كِبَارٌ ist Plural; gebraucht wird der Dual.","أَخَوَانِ ist unbestimmt; das Adjektiv darf kein الْ haben."],["سَهْلٌ ist unbestimmt, الْكِتَابُ bestimmt – also kein Adjektiv.","Mubtadaʾ ist الْكِتَابُ.","Ein Badal ersetzt ein Wort; سَهْلٌ ist die Aussage."],["أُخْتٌ ist weiblich: صَغِيرَةٌ mit ة.","أُخْتٌ ist unbestimmt; das Adjektiv darf kein الْ haben.","Das Adjektiv steht hinter dem Nomen, nicht als Muḍāf davor."],["نَعْتٌ ist das beschreibende Wort, nicht das beschriebene.","مُبْتَدَأٌ ist das Subjekt des Nominalsatzes.","مُضَافٌ ist das erste Glied der Iḍāfa."],["إِخْوَةٌ sind Personen im Plural; das Adjektiv steht auch im Plural.","كَبِيرَانِ ist Dual.","إِخْوَةٌ ist unbestimmt; das Adjektiv darf kein الْ haben."]],"i":[["Vor الْجَدِيدِ steht kein Muḍāf; الْمُدَرِّسِ hat den Artikel.","Die Präposition لِـ gehört zu الْمُدَرِّسِ; الْجَدِيدِ beschreibt es.","Ein Badal ersetzt ein Wort; ein Adjektiv, das beschreibt, ist Naʿt."],["Das Khabar ist لَهُ; كَبِيرَانِ beschreibt أَخَوَانِ.","Mubtadaʾ ist أَخَوَانِ (nachgestellt).","أَخَوَانِ steht im Nominativ, also auch كَبِيرَانِ (-āni)."],["الْجَدِيدُ ist bestimmt wie الْكِتَابُ – also Adjektiv; das Khabar ist سَهْلٌ.","Ein zweites Mubtadaʾ gibt es nicht.","Ein Adjektiv, das mit seinem Nomen übereinstimmt, ist Naʿt, kein Badal."],["سَهْلٌ ist unbestimmt nach einem bestimmten Nomen – also Aussage.","Mubtadaʾ ist الْكِتَابُ.","Ein Ḥāl steht im Akkusativ; سَهْلٌ hat -un."]]}
};
